-- Additional MTH 101 (Elementary Mathematics I) CBT questions mined from a
-- second, much more detailed source (a full theory textbook, 220 scanned
-- pages), appended to the existing 174-question bank built from a "Solved
-- Problem Sets" workbook. Does not touch prior rows.
--
-- 264 rows. Every answer independently sympy-verified, not trusted
-- from the textbook's own worked examples or answer key. A couple of real
-- discrepancies in the source were caught and corrected in the process
-- (see commit message for detail).
--
-- Deliberately excluded as outside the official MTH 101 syllabus: general
-- function theory/relations, exponential and logarithmic functions, rational
-- functions and inequalities, permutations and combinations, the binomial
-- theorem for a real (non-integer) index, and solution of triangles
-- (sine/cosine rule) -- all covered by this same textbook but not listed in
-- the MTH 101 course outline.

insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level,
   question, options, correct_index, explanation, topic, is_general,
   semester, units)
values
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are the factors of $2x^3-9x^2+3x+4$?', '["$(x-1)(x-4)(2x+1)$", "$(x+1)(x-4)(2x-1)$", "$(x-1)(x+4)(2x+1)$", "$(x-2)(x-4)(2x+1)$"]'::jsonb, 0, 'Testing $x=1$ gives $2-9+3+4=0$, so $(x-1)$ is a factor; dividing leaves $2x^2-7x-4=(x-4)(2x+1)$. So $2x^3-9x^2+3x+4=(x-1)(x-4)(2x+1)$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are the factors of $x^3+x^2+2x+2$?', '["$(x+1)(x^2+2)$", "$(x-1)(x^2+2)$", "$(x+1)(x^2-2)$", "$(x+2)(x^2+1)$"]'::jsonb, 0, 'Testing $x=-1$ gives $-1+1-2+2=0$, so $(x+1)$ is a factor; dividing gives $x^3+x^2+2x+2=(x+1)(x^2+2)$, and $x^2+2$ has no real linear factors since it is always positive.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are the solutions of $2x^2-7x-4=0$?', '["$x=4$ or $x=-\\dfrac12$", "$x=-4$ or $x=\\dfrac12$", "$x=2$ or $x=-1$", "$x=4$ or $x=\\dfrac12$"]'::jsonb, 0, 'The discriminant is $(-7)^2-4(2)(-4)=81$, so $x=\dfrac{7\pm9}{4}$, giving $x=4$ or $x=-\dfrac12$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are the solutions of $-3x^2+15x-10=0$?', '["$x=\\dfrac{15\\pm\\sqrt{105}}{6}$", "$x=\\dfrac{15\\pm\\sqrt{105}}{3}$", "$x=\\dfrac{5\\pm\\sqrt{105}}{6}$", "$x=15\\pm\\sqrt{105}$"]'::jsonb, 0, 'The discriminant is $15^2-4(-3)(-10)=225-120=105$, so $x=\dfrac{-15\pm\sqrt{105}}{2(-3)}=\dfrac{15\mp\sqrt{105}}{6}$; the two roots are approximately $0.79$ and $4.21$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'How many real solutions does $-3x^2+7x-5=0$ have?', '["Two distinct real solutions", "One repeated real solution", "No real solutions", "Three real solutions"]'::jsonb, 2, 'The discriminant is $7^2-4(-3)(-5)=49-60=-11$, which is negative, so there are no real solutions.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'The product of two consecutive odd integers is $483$. What are the integers (taking the positive pair)?', '["$19$ and $21$", "$21$ and $23$", "$23$ and $25$", "$20$ and $22$"]'::jsonb, 1, 'Letting $x$ be the smaller odd integer, $x(x+2)=483$ gives $x^2+2x-483=0$, whose positive solution is $x=21$, so the integers are $21$ and $23$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the solution of $4^x-2^x-12=0$?', '["$x=2$", "$x=3$", "$x=\\log_2 12$", "$x=4$"]'::jsonb, 0, 'Substituting $y=2^x$ gives $y^2-y-12=0$, i.e. $(y-4)(y+3)=0$, so $y=4$ (since $y=-3$ is impossible for $2^x$). Then $2^x=4$ gives $x=2$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are the real solutions of $-x^4+x^2+6=0$?', '["$x=\\pm\\sqrt{3}$", "$x=\\pm\\sqrt{2}$", "$x=\\pm 3$", "$x=\\pm\\sqrt{6}$"]'::jsonb, 0, 'Substituting $y=x^2$ gives $y^2-y-6=0$, i.e. $(y-3)(y+2)=0$, so $y=3$ (since $y=-2$ is impossible for $x^2$). Then $x^2=3$ gives $x=\pm\sqrt3$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A rectangle has perimeter $36$ m and area $56$ m$^2$. What are its dimensions?', '["$5$ m by $13$ m", "$4$ m by $14$ m", "$6$ m by $12$ m", "$7$ m by $11$ m"]'::jsonb, 1, 'With length $x$ and width $18-x$ (from $2x+2y=36$), the area equation $x(18-x)=56$ gives $x^2-18x+56=0$, i.e. $(x-4)(x-14)=0$, so the dimensions are $4$ m by $14$ m.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\alpha$ and $\beta$ are the (nonzero) roots of $x^2+px+q=0$, what quadratic equation has roots $\dfrac1\alpha$ and $\dfrac1\beta$?', '["$qx^2+px+1=0$", "$x^2+px+q=0$", "$qx^2-px+1=0$", "$px^2+qx+1=0$"]'::jsonb, 0, 'Since $\alpha+\beta=-p$ and $\alpha\beta=q$, the sum of the reciprocals is $\frac1\alpha+\frac1\beta=\frac{\alpha+\beta}{\alpha\beta}=-\frac{p}{q}$ and their product is $\frac{1}{\alpha\beta}=\frac1q$. A quadratic with these roots is $x^2+\frac{p}{q}x+\frac1q=0$, which clears to $qx^2+px+1=0$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'One root of $9x^2+bx+3=0$ is the square of the reciprocal of the other. What is $b$?', '["$b=-28$", "$b=28$", "$b=-9$", "$b=-21$"]'::jsonb, 0, 'If the roots are $\alpha$ and $\beta=1/\alpha^2$, then $\alpha\beta=1/\alpha=3/9=1/3$ gives $\alpha=3$, so $\beta=1/9$. Then $\alpha+\beta=\frac{28}{9}=-b/9$, giving $b=-28$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\alpha$ and $\beta$ are the roots of $x^2-3x+1=0$, what is $\alpha^2+\beta^2$?', '["$9$", "$7$", "$5$", "$11$"]'::jsonb, 1, '$\alpha+\beta=3$ and $\alpha\beta=1$, so $\alpha^2+\beta^2=(\alpha+\beta)^2-2\alpha\beta=9-2=7$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\alpha$ and $\beta$ are the roots of $x^2-3x+1=0$, what is $(\alpha-\beta)^2$?', '["$9$", "$7$", "$1$", "$5$"]'::jsonb, 3, '$(\alpha-\beta)^2=(\alpha+\beta)^2-4\alpha\beta=9-4=5$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\alpha$ and $\beta$ are the roots of $x^2-3x+1=0$, what is $\alpha^3+\beta^3$?', '["$18$", "$27$", "$21$", "$15$"]'::jsonb, 0, '$\alpha^3+\beta^3=(\alpha+\beta)\big[(\alpha+\beta)^2-3\alpha\beta\big]=3(9-3)=18$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are the solutions of $x^2-12=0$?', '["$x=\\pm 2\\sqrt3$", "$x=\\pm\\sqrt{12}$ only positive", "$x=\\pm 6$", "$x=\\pm 3\\sqrt2$"]'::jsonb, 0, '$x^2=12$ gives $x=\pm\sqrt{12}=\pm2\sqrt3$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are the solutions of $48-3x^2=0$?', '["$x=\\pm 16$", "$x=\\pm 4$", "$x=\\pm 8$", "$x=\\pm\\sqrt{48}$ only"]'::jsonb, 1, '$3x^2=48$ gives $x^2=16$, so $x=\pm4$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are the solutions of $x^2=2x$?', '["$x=0$ or $x=2$", "$x=0$ or $x=-2$", "$x=2$ only", "$x=0$ only"]'::jsonb, 0, 'Rearranging gives $x^2-2x=0$, i.e. $x(x-2)=0$, so $x=0$ or $x=2$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are the solutions of $3x^2+30x+72=0$?', '["$x=-4$ or $x=-6$", "$x=4$ or $x=6$", "$x=-2$ or $x=-12$", "$x=-3$ or $x=-8$"]'::jsonb, 0, 'Dividing by $3$ gives $x^2+10x+24=0$, i.e. $(x+4)(x+6)=0$, so $x=-4$ or $x=-6$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the solution of $9x^2-12x+4=0$?', '["$x=\\dfrac23$ (a repeated root)", "$x=\\dfrac34$ (a repeated root)", "$x=\\dfrac23$ or $x=-\\dfrac23$", "$x=\\dfrac43$ (a repeated root)"]'::jsonb, 0, 'The discriminant is $(-12)^2-4(9)(4)=144-144=0$, so there is one repeated root $x=\dfrac{12}{18}=\dfrac23$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are the solutions of $x^2+20=9x$?', '["$x=4$ or $x=5$", "$x=-4$ or $x=-5$", "$x=2$ or $x=10$", "$x=1$ or $x=20$"]'::jsonb, 0, 'Rearranging gives $x^2-9x+20=0$, i.e. $(x-4)(x-5)=0$, so $x=4$ or $x=5$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are the solutions of $x^2+\sqrt{8}\,x-6=0$?', '["$x=\\sqrt2$ or $x=-3\\sqrt2$", "$x=2\\sqrt2$ or $x=-\\sqrt2$", "$x=\\sqrt2$ or $x=3\\sqrt2$", "$x=-\\sqrt2$ or $x=-3\\sqrt2$"]'::jsonb, 0, 'Since $\sqrt8=2\sqrt2$, factoring gives $(x-\sqrt2)(x+3\sqrt2)=0$ because $\sqrt2\cdot(-3\sqrt2)=-6$ and $\sqrt2+(-3\sqrt2)=-2\sqrt2=-\sqrt8$. So $x=\sqrt2$ or $x=-3\sqrt2$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'The product of two consecutive odd integers is $35$. What are the integers (taking the positive pair)?', '["$3$ and $5$", "$5$ and $7$", "$7$ and $9$", "$1$ and $35$"]'::jsonb, 1, 'With $x$ the smaller odd integer, $x(x+2)=35$ gives $x^2+2x-35=0$, i.e. $(x-5)(x+7)=0$, so $x=5$, giving the integers $5$ and $7$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A rectangular lot measuring $20$ m by $40$ m is surrounded by a border of uniform width, which triples the total area to $2400$ m$^2$. What is the width of the border?', '["$5$ m", "$10$ m", "$8$ m", "$12$ m"]'::jsonb, 1, 'With border width $w$, $(20+2w)(40+2w)=2400$ simplifies to $4w^2+120w-1600=0$, i.e. $w^2+30w-400=0$, i.e. $(w-10)(w+40)=0$. The positive solution is $w=10$ m.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What quadratic equation (in the form $x^2+bx+c=0$) has roots whose sum is $10$ and whose product is $4$?', '["$x^2-10x+4=0$", "$x^2+10x+4=0$", "$x^2-4x+10=0$", "$x^2-10x-4=0$"]'::jsonb, 0, 'For a quadratic $x^2-(\text{sum})x+(\text{product})=0$, using sum $10$ and product $4$ gives $x^2-10x+4=0$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\alpha$ and $\beta$ are the roots of $2x^2-10x+7=0$, what is $\alpha^2+\beta^2$?', '["$25$", "$18$", "$20$", "$14$"]'::jsonb, 1, '$\alpha+\beta=5$ and $\alpha\beta=\dfrac72$, so $\alpha^2+\beta^2=5^2-2\left(\dfrac72\right)=25-7=18$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\alpha$ and $\beta$ are the roots of $2x^2-10x+7=0$, what is $\alpha^4+\beta^4$?', '["$\\dfrac{599}{2}$", "$\\dfrac{625}{2}$", "$324$", "$\\dfrac{343}{2}$"]'::jsonb, 0, 'Since $\alpha^2+\beta^2=18$ and $\alpha\beta=\dfrac72$, $\alpha^4+\beta^4=(\alpha^2+\beta^2)^2-2(\alpha\beta)^2=324-2\left(\dfrac{49}{4}\right)=324-\dfrac{49}{2}=\dfrac{599}{2}$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\alpha$ and $\beta$ are the roots of $x^2-4x+1=0$, what is $\alpha^3+\beta^3$?', '["$52$", "$60$", "$44$", "$64$"]'::jsonb, 0, '$\alpha+\beta=4$ and $\alpha\beta=1$, so $\alpha^3+\beta^3=(\alpha+\beta)\big[(\alpha+\beta)^2-3\alpha\beta\big]=4(16-3)=52$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\alpha$ and $\beta$ are the roots of $x^2-4x+1=0$, what is $\alpha^6+\beta^6$?', '["$2702$", "$2704$", "$2600$", "$2500$"]'::jsonb, 0, 'With $\alpha^2+\beta^2=14$ and $\alpha\beta=1$: $\alpha^4+\beta^4=14^2-2=194$, and $\alpha^6+\beta^6=(\alpha^2+\beta^2)(\alpha^4+\beta^4)-(\alpha\beta)^2(\alpha^2+\beta^2)=14(194)-14=2702$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are the real solutions of $-x^4+2x^2+3=0$?', '["$x=\\pm\\sqrt3$", "$x=\\pm1$", "$x=\\pm\\sqrt2$", "$x=\\pm3$"]'::jsonb, 0, 'Substituting $y=x^2$ gives $-y^2+2y+3=0$, i.e. $y^2-2y-3=0$, i.e. $(y-3)(y+1)=0$, so $y=3$ (the only value valid for $x^2$). Then $x=\pm\sqrt3$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are the solutions of $2x^2-5x-3=0$?', '["$x=3$ or $x=-\\dfrac12$", "$x=-3$ or $x=\\dfrac12$", "$x=3$ or $x=\\dfrac12$", "$x=1$ or $x=-\\dfrac32$"]'::jsonb, 0, 'Factoring gives $(x-3)(2x+1)=0$, so $x=3$ or $x=-\dfrac12$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are the solutions of $5x^2+2x-3=0$?', '["$x=\\dfrac35$ or $x=-1$", "$x=-\\dfrac35$ or $x=1$", "$x=\\dfrac35$ or $x=1$", "$x=\\dfrac53$ or $x=-1$"]'::jsonb, 0, 'Factoring gives $(5x-3)(x+1)=0$, so $x=\dfrac35$ or $x=-1$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'The product of two consecutive even integers is $120$. What are the integers (taking the positive pair)?', '["$8$ and $10$", "$10$ and $12$", "$12$ and $14$", "$6$ and $20$"]'::jsonb, 1, 'With $x$ the smaller even integer, $x(x+2)=120$ gives $x^2+2x-120=0$, i.e. $(x-10)(x+12)=0$, so $x=10$, giving the integers $10$ and $12$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'One root of $x^2+bx+c=0$ is twice the other, and the sum of the roots is $-15$. What are $b$ and $c$?', '["$b=15$, $c=50$", "$b=-15$, $c=50$", "$b=15$, $c=-50$", "$b=30$, $c=50$"]'::jsonb, 0, 'If the roots are $\alpha$ and $2\alpha$, then $3\alpha=-15$ gives $\alpha=-5$, so the roots are $-5$ and $-10$. Then $b=-(\alpha+2\alpha)=15$ and $c=\alpha\cdot2\alpha=50$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'The roots of $x^2+3x+2=0$ are $-1$ and $-2$. What quadratic equation has roots $(-1-1)^2=4$ and $(-2-1)^2=9$?', '["$x^2-13x+36=0$", "$x^2+13x+36=0$", "$x^2-13x-36=0$", "$x^2-6x+9=0$"]'::jsonb, 0, 'With roots $4$ and $9$, the sum is $13$ and the product is $36$, giving the quadratic $x^2-13x+36=0$.', 'Theory of Quadratic Equations', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Which of the following double inequalities is true?', '["$1 \\le \\dfrac{6}{4} \\le 2$", "$-1 \\le 2 < 1$", "$\\dfrac12 > \\dfrac14 > 1$", "$-1 < -2 < 3$"]'::jsonb, 0, 'Only $1 \le \tfrac{6}{4} \le 2$ holds, since $\tfrac64=1.5$ lies between $1$ and $2$. The others fail: $2<1$ is false, $\tfrac14>1$ is false, and $-1<-2$ is false.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Which of the following numbers satisfies $-3 < x \le 5$?', '["$-3$", "$6$", "$5$", "$-4$"]'::jsonb, 2, 'The interval excludes $-3$ (strict inequality) but includes $5$. So $x=5$ satisfies it, while $6$ and $-4$ fall outside the interval.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Which of the following numbers satisfies $3 < x < 8$?', '["$3$", "$8$", "$5$", "$9$"]'::jsonb, 2, 'The interval is open at both ends, so $3$ and $8$ are excluded. Only $5$ lies strictly between them.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'For which value of $x$ is $|x-1|\le 2$ true?', '["$-2$", "$4$", "$-3$", "$0$"]'::jsonb, 3, '$|x-1|\le 2$ means $-1\le x\le 3$. Only $x=0$ lies in this range; the others give $|x-1|=3,3,4$ respectively, all exceeding $2$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'How many integers $n$ satisfy $|n-1|\le 2$?', '["4", "6", "5", "3"]'::jsonb, 2, '$|n-1|\le 2$ means $-1\le n\le 3$, giving the integers $-1,0,1,2,3$ — five integers in total.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'How many integers $n$ satisfy $|n| < 5$?', '["10", "8", "11", "9"]'::jsonb, 3, '$|n|<5$ means $-4\le n\le 4$, giving the nine integers $-4,-3,-2,-1,0,1,2,3,4$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $|3-5|$?', '["$-2$", "$8$", "$2$", "$0$"]'::jsonb, 2, '$3-5=-2$, and $|-2|=2$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\left|-6+\dfrac{3}{2}\right|$?', '["$\\dfrac{9}{2}$", "$\\dfrac{7}{2}$", "$6$", "$-\\dfrac{9}{2}$"]'::jsonb, 0, '$-6+\tfrac32=-\tfrac{9}{2}$, and its absolute value is $\tfrac{9}{2}$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $|-2(18-6)|$?', '["$12$", "$-24$", "$36$", "$24$"]'::jsonb, 3, '$18-6=12$, so $-2(12)=-24$, and $|-24|=24$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $|-4(6-15)|$?', '["$36$", "$-36$", "$9$", "$44$"]'::jsonb, 0, '$6-15=-9$, so $-4(-9)=36$, and $|36|=36$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\dfrac{6-14}{|3-7|}$?', '["$2$", "$-2$", "$-8$", "$8$"]'::jsonb, 1, '$6-14=-8$ and $|3-7|=4$, so the quotient is $\dfrac{-8}{4}=-2$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\left|\dfrac{7}{11}\cdot(-2)\right|$?', '["$-\\dfrac{14}{11}$", "$\\dfrac{7}{11}$", "$\\dfrac{14}{11}$", "$2$"]'::jsonb, 2, '$\dfrac{7}{11}\cdot(-2)=-\dfrac{14}{11}$, and its absolute value is $\dfrac{14}{11}$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\dfrac{|-5|}{\left|\frac{3}{2}\right|}$?', '["$\\dfrac{10}{3}$", "$\\dfrac{3}{10}$", "$-\\dfrac{10}{3}$", "$\\dfrac{15}{2}$"]'::jsonb, 0, '$|-5|=5$ and $|\tfrac32|=\tfrac32$, so the quotient is $5\div\tfrac32=\dfrac{10}{3}$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\big|\,|2-4|-7\,\big|$?', '["$-5$", "$9$", "$-9$", "$5$"]'::jsonb, 3, '$|2-4|=2$, so $2-7=-5$, and $|-5|=5$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Which expression is equivalent to $x^3\cdot x^6$?', '["$x^{18}$", "$x^{2}$", "$x^{9}$", "$2x^{9}$"]'::jsonb, 2, 'When multiplying powers of the same base, exponents are added: $x^3\cdot x^6=x^{3+6}=x^9$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $2^3\cdot 2^4$?', '["$64$", "$32$", "$256$", "$128$"]'::jsonb, 3, '$2^3\cdot 2^4=2^7=128$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Which expression is equivalent to $\dfrac{x^5}{x^6}$?', '["$x$", "$\\dfrac{1}{x}$", "$x^{11}$", "$-x$"]'::jsonb, 1, 'Since the denominator has the larger exponent, $\dfrac{x^5}{x^6}=\dfrac{1}{x^{6-5}}=\dfrac{1}{x}$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Which expression is equivalent to $(x^3)^4$?', '["$x^7$", "$x^{81}$", "$x^{12}$", "$4x^3$"]'::jsonb, 2, 'Raising a power to a power multiplies the exponents: $(x^3)^4=x^{3\cdot4}=x^{12}$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Which expression is equivalent to $(2x^3)\cdot(7x^5)$?', '["$9x^{15}$", "$14x^{8}$", "$14x^{15}$", "$9x^{8}$"]'::jsonb, 1, 'Multiply the coefficients and add the exponents: $2\cdot 7=14$ and $x^3\cdot x^5=x^8$, giving $14x^8$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Which expression is equivalent to $x^4\cdot x^{-6}$?', '["$x^{2}$", "$x^{-24}$", "$\\dfrac{1}{x^{2}}$", "$-x^2$"]'::jsonb, 2, '$x^4\cdot x^{-6}=x^{4-6}=x^{-2}=\dfrac{1}{x^2}$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Which expression is equivalent to $(5y^2)(4y^{-7})$?', '["$20y^{5}$", "$9y^{-5}$", "$\\dfrac{9}{y^{5}}$", "$\\dfrac{20}{y^{5}}$"]'::jsonb, 3, 'Multiplying coefficients gives $5\cdot4=20$, and adding exponents gives $y^{2-7}=y^{-5}$, so the product is $20y^{-5}=\dfrac{20}{y^5}$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Which expression is equivalent to $(2x^2y^{-2}z^7)(3x^3y^4z^{-2})$?', '["$6x^5y^2z^5$", "$6x^5y^{-6}z^9$", "$5x^5y^2z^5$", "$6x^6y^2z^{14}$"]'::jsonb, 0, 'Multiply the coefficients ($2\cdot3=6$) and add exponents of like bases: $x^{2+3}=x^5$, $y^{-2+4}=y^2$, $z^{7-2}=z^5$, giving $6x^5y^2z^5$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are all the real fourth roots of $16$?', '["only $2$", "$2$ and $-2$", "$4$ and $-4$", "only $-2$"]'::jsonb, 1, 'Since $2^4=16$ and $(-2)^4=16$, both $2$ and $-2$ are fourth roots of $16$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $27^{-4/3}$?', '["$\\dfrac{1}{81}$", "$81$", "$-81$", "$\\dfrac{1}{9}$"]'::jsonb, 0, '$27^{1/3}=3$, so $27^{4/3}=3^4=81$, and therefore $27^{-4/3}=\dfrac{1}{81}$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the real cube root of $-64$?', '["$4$", "$-4$", "$-8$", "$8$"]'::jsonb, 1, '$(-4)^3=-64$, so the cube root of $-64$ is $-4$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $4^{3/2}$?', '["$6$", "$64$", "$8$", "$12$"]'::jsonb, 2, '$4^{3/2}=(4^{1/2})^3=2^3=8$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is $\sqrt{2}+\sqrt{32}-\sqrt{512}$ in simplified surd form?', '["$-11\\sqrt{2}$", "$5\\sqrt{2}$", "$11\\sqrt{2}$", "$-9\\sqrt{2}$"]'::jsonb, 0, '$\sqrt{32}=4\sqrt2$ and $\sqrt{512}=16\sqrt2$, so the expression is $\sqrt2+4\sqrt2-16\sqrt2=-11\sqrt2$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the simplified form of $\sqrt{75}\cdot\sqrt{135}$?', '["$45\\sqrt{5}$", "$15\\sqrt{5}$", "$45\\sqrt{3}$", "$225$"]'::jsonb, 0, '$\sqrt{75}\cdot\sqrt{135}=\sqrt{10125}$, and factoring gives $\sqrt{75}=5\sqrt3$, $\sqrt{135}=3\sqrt{15}$, whose product is $15\sqrt{45}=15\cdot3\sqrt5=45\sqrt5$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the simplified value of $1+3\sqrt{2}-\sqrt{18}$?', '["$1$", "$1+6\\sqrt2$", "$-2$", "$4-\\sqrt{2}$"]'::jsonb, 0, '$\sqrt{18}=3\sqrt2$, so $1+3\sqrt2-3\sqrt2=1$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $(\sqrt{2}-\sqrt{3})(\sqrt{2}+\sqrt{3})$?', '["$-1$", "$1$", "$5$", "$-5$"]'::jsonb, 0, 'This is a difference of squares: $(\sqrt2)^2-(\sqrt3)^2=2-3=-1$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Which single square root equals $3\sqrt{7}$?', '["$\\sqrt{21}$", "$\\sqrt{49}$", "$\\sqrt{63}$", "$\\sqrt{10}$"]'::jsonb, 2, '$3\sqrt7=\sqrt{3^2\cdot7}=\sqrt{63}$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the simplified value of $\sqrt{5}\times\sqrt{20}$?', '["$10$", "$100$", "$5\\sqrt{20}$", "$25$"]'::jsonb, 0, '$\sqrt5\times\sqrt{20}=\sqrt{100}=10$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the simplified value of $\sqrt{8}\times\sqrt{3}$?', '["$\\sqrt{11}$", "$2\\sqrt{6}$", "$4\\sqrt{6}$", "$24$"]'::jsonb, 1, '$\sqrt8\times\sqrt3=\sqrt{24}=\sqrt{4\cdot6}=2\sqrt6$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is $\dfrac{3}{\sqrt{3}}$ after rationalizing the denominator?', '["$\\sqrt{3}$", "$3\\sqrt{3}$", "$\\dfrac{\\sqrt3}{3}$", "$1$"]'::jsonb, 0, 'Multiplying numerator and denominator by $\sqrt3$ gives $\dfrac{3\sqrt3}{3}=\sqrt3$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is $\dfrac{6}{\sqrt{7}}$ after rationalizing the denominator?', '["$\\dfrac{6\\sqrt{7}}{7}$", "$\\dfrac{\\sqrt7}{6}$", "$6\\sqrt7$", "$\\dfrac{7\\sqrt6}{6}$"]'::jsonb, 0, 'Multiplying numerator and denominator by $\sqrt7$ gives $\dfrac{6\sqrt7}{7}$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is $\sqrt{\dfrac{4}{5}}$ after rationalizing the denominator?', '["$\\dfrac{2\\sqrt{5}}{5}$", "$\\dfrac{2}{5}$", "$\\dfrac{4\\sqrt5}{5}$", "$\\dfrac{\\sqrt5}{2}$"]'::jsonb, 0, '$\sqrt{4/5}=\dfrac{2}{\sqrt5}$, and rationalizing gives $\dfrac{2\sqrt5}{5}$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the simplified value of $\sqrt{45}+\sqrt{5}$?', '["$\\sqrt{50}$", "$4\\sqrt{5}$", "$3\\sqrt{5}$", "$8\\sqrt{5}$"]'::jsonb, 1, '$\sqrt{45}=3\sqrt5$, so $\sqrt{45}+\sqrt5=3\sqrt5+\sqrt5=4\sqrt5$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the simplified value of $3\sqrt{2}-2\sqrt{8}+\sqrt{32}$?', '["$3\\sqrt{2}$", "$5\\sqrt2$", "$\\sqrt2$", "$9\\sqrt2$"]'::jsonb, 0, '$\sqrt8=2\sqrt2$ and $\sqrt{32}=4\sqrt2$, so the expression is $3\sqrt2-4\sqrt2+4\sqrt2=3\sqrt2$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the simplified value of $\sqrt{18}-3\sqrt{8}+5\sqrt{50}$?', '["$22\\sqrt{2}$", "$16\\sqrt2$", "$28\\sqrt2$", "$20\\sqrt2$"]'::jsonb, 0, '$\sqrt{18}=3\sqrt2$, $\sqrt8=2\sqrt2$, $\sqrt{50}=5\sqrt2$, so the expression is $3\sqrt2-6\sqrt2+25\sqrt2=22\sqrt2$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the simplified value of $4\sqrt{28}-5\sqrt{63}+2\sqrt{112}$?', '["$\\sqrt{7}$", "$3\\sqrt7$", "$-\\sqrt7$", "$5\\sqrt7$"]'::jsonb, 0, '$\sqrt{28}=2\sqrt7$, $\sqrt{63}=3\sqrt7$, $\sqrt{112}=4\sqrt7$, so the expression is $8\sqrt7-15\sqrt7+8\sqrt7=\sqrt7$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is $\dfrac{7\sqrt{6}}{\sqrt{2}}$ in simplified surd form?', '["$7\\sqrt{3}$", "$7\\sqrt{12}$", "$3.5\\sqrt6$", "$\\sqrt3$"]'::jsonb, 0, '$\dfrac{7\sqrt6}{\sqrt2}=7\sqrt{6/2}=7\sqrt3$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is $\dfrac{1}{5-\sqrt{3}}$ after rationalizing the denominator?', '["$\\dfrac{5+\\sqrt3}{22}$", "$\\dfrac{5-\\sqrt3}{22}$", "$\\dfrac{5+\\sqrt3}{28}$", "$5+\\sqrt3$"]'::jsonb, 0, 'Multiplying by $\dfrac{5+\sqrt3}{5+\sqrt3}$ gives $\dfrac{5+\sqrt3}{25-3}=\dfrac{5+\sqrt3}{22}$.', 'Real Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A series has general term $3+2n$ for $n=1,2,3,\ldots$. What is the sum of its first five terms?', '["40", "45", "50", "35"]'::jsonb, 1, 'The terms for $n=1$ to $5$ are $5,7,9,11,13$, which add up to $45$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A series has general term $3+2n$ for $n=1,2,3,\ldots$. What is its fifth term (the term at $n=5$)?', '["11", "15", "13", "10"]'::jsonb, 2, 'Substituting $n=5$ gives $3+2(5)=13$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A sequence is defined by $t_n=\dfrac{n^2+n}{2}$ for $n=0,1,2,\ldots$. What is the sum $t_0+t_1+t_2+t_3+t_4+t_5$?', '["36", "30", "35", "45"]'::jsonb, 2, 'The terms are $0,1,3,6,10,15$, which sum to $35$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A sequence is defined by $t_n=\dfrac{n^2+n}{2}$ for $n=0,1,2,\ldots$. What is the value of $t_5$?', '["10", "20", "15", "12"]'::jsonb, 2, '$t_5=\dfrac{5^2+5}{2}=\dfrac{30}{2}=15$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A sequence satisfies $u(0)=1$ and $u(n)=\dfrac{u(n-1)}{n}$ for $n\ge 1$. What is $u(4)$?', '["$\\dfrac{1}{6}$", "$\\dfrac{1}{12}$", "$\\dfrac{1}{4}$", "$\\dfrac{1}{24}$"]'::jsonb, 3, 'Computing successively, $u(1)=1,\ u(2)=\tfrac12,\ u(3)=\tfrac16,\ u(4)=\tfrac{1}{24}$ (in fact $u(n)=1/n!$).', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A sequence satisfies $u(0)=1$ and $u(n)=\dfrac{u(n-1)}{n}$ for $n\ge 1$. What is $u(0)+u(1)+u(2)+u(3)$?', '["$\\dfrac{5}{2}$", "$3$", "$\\dfrac{8}{3}$", "$\\dfrac{7}{3}$"]'::jsonb, 2, 'The first four terms are $1,\,1,\,\tfrac12,\,\tfrac16$, and $1+1+\tfrac12+\tfrac16=\tfrac{8}{3}$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A sequence has general term $\dfrac{n(n+1)}{2}$ for positive integers $n$. What is its 10th term?', '["45", "50", "60", "55"]'::jsonb, 3, '$\dfrac{10\cdot 11}{2}=55$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'The sum of the finite series $0+1+2+\cdots+k$ equals $\dfrac{k(k+1)}{2}$. What is $0+1+2+3+4+5+6$?', '["15", "28", "20", "21"]'::jsonb, 3, 'With $k=6$, $\dfrac{6\cdot 7}{2}=21$, matching the direct sum $0+1+2+3+4+5+6=21$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the sum of the first five terms of the series $\dfrac12+\dfrac14+\dfrac18+\cdots+\dfrac{1}{2^n}+\cdots$ (i.e. $n=1$ through $n=5$)?', '["$\\dfrac{15}{16}$", "$\\dfrac{63}{64}$", "$1$", "$\\dfrac{31}{32}$"]'::jsonb, 3, 'The $k$-th partial sum of $\sum \frac{1}{2^n}$ is $1-\frac{1}{2^k}$; for $k=5$ this is $1-\frac{1}{32}=\frac{31}{32}$.', 'Sequences and Series', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the coefficient of $x^3$ in the expansion of $(2+x)^6$?', '["120", "160", "192", "240"]'::jsonb, 1, 'The general term is $\binom{6}{r}2^{6-r}x^r$. For $r=3$, the term is $\binom{6}{3}2^3x^3 = 20\cdot 8\, x^3 = 160x^3$, so the coefficient is 160.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the coefficient of $x^4$ in the expansion of $(4-x)^5$?', '["-160", "-20", "20", "160"]'::jsonb, 2, 'The general term is $\binom{5}{r}4^{5-r}(-x)^r$. For $r=4$, this is $\binom{5}{4}4^1(-x)^4 = 5\cdot 4\, x^4 = 20x^4$, so the coefficient is 20.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'In the expansion of $\left(x^2+\dfrac{1}{x^3}\right)^4$ in ascending powers of $x$, what is the coefficient of $x^{-2}$?', '["4", "6", "8", "12"]'::jsonb, 1, 'Expanding gives $\left(x^2+\frac{1}{x^3}\right)^4 = x^{-12}+4x^{-7}+6x^{-2}+4x^3+x^8$, so the coefficient of $x^{-2}$ is 6.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'For how many positive integer values of $n$ does the coefficient of $x^4$ vanish in the expansion of $(1+x)(1-x)^n$?', '["1", "2", "3", "4"]'::jsonb, 2, 'The coefficient of $x^4$ in $(1+x)(1-x)^n$ equals $\binom{n}{4}-\binom{n}{3}$. This equals zero exactly when $n=1$, $n=2$, or $n=7$, giving 3 positive integer values.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $(1+\sqrt{2})^5-(\sqrt{2}-1)^5$?', '["40", "42", "82", "124"]'::jsonb, 2, 'Expanding both fifth powers by the binomial theorem and subtracting, all terms with even powers of $\sqrt2$ cancel while the odd-power terms double, leaving $2\left[\binom{5}{2}(\sqrt2)^2+\binom{5}{4}(\sqrt2)^4\right]=2(20+20)=82$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'In the expansion of $(a+2x^3)^{17}$, what is the coefficient of the term containing $a^{13}x^{12}$?', '["2380", "9520", "19040", "38080"]'::jsonb, 3, 'The term containing $a^{13}x^{12}$ corresponds to $r=4$: $\binom{17}{4}a^{13}(2x^3)^4=2380\cdot 16\,a^{13}x^{12}=38080\,a^{13}x^{12}$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\binom{10}{0}+\binom{10}{1}+\binom{10}{2}+\cdots+\binom{10}{10}$?', '["512", "1000", "1024", "2048"]'::jsonb, 2, 'Putting $x=1$ in $(1+x)^{10}=\sum_{r=0}^{10}\binom{10}{r}x^r$ gives $\sum_{r=0}^{10}\binom{10}{r}=2^{10}=1024$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\binom{8}{0}+\binom{8}{2}+\binom{8}{4}+\binom{8}{6}+\binom{8}{8}$?', '["64", "128", "156", "256"]'::jsonb, 1, 'The sum of binomial coefficients at even positions equals half of $2^8$, i.e. $2^{8-1}=128$. This can be checked directly: $1+28+70+28+1=128$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the coefficient of $x^2y^2z$ in the expansion of $(x+y+z)^5$?', '["10", "20", "30", "60"]'::jsonb, 2, 'The coefficient of $x^2y^2z^1$ is the multinomial coefficient $\dfrac{5!}{2!\,2!\,1!}=30$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the coefficient of $t^2$ in the expansion of $(1-3t)^7$?', '["21", "63", "189", "567"]'::jsonb, 2, 'The term is $\binom{7}{2}(-3t)^2=21\cdot 9\,t^2=189t^2$, so the coefficient is 189.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the coefficient of $x^{20}$ in the expansion of $(x^2+3x)^{12}$?', '["7920", "13365", "40095", "58995"]'::jsonb, 2, 'Writing the general term as $\binom{12}{k}x^{2(12-k)}(3x)^k=\binom{12}{k}3^k x^{24-k}$, the power $24-k=20$ gives $k=4$, so the coefficient is $\binom{12}{4}3^4=495\cdot 81=40095$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the coefficient of $a^{24}$ in the expansion of $(3a^4-5)^8$?', '["102060", "255150", "510300", "612360"]'::jsonb, 2, 'The general term is $\binom{8}{k}(3a^4)^k(-5)^{8-k}$. The power $4k=24$ gives $k=6$, so the coefficient is $\binom{8}{6}3^6(-5)^2=28\cdot 729\cdot 25=510300$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'In the expansion of $\left(3u+\dfrac{2}{u}\right)^{12}$, the 10th term has the form $\dfrac{k}{u^6}$. What is $k$?', '["506880", "1520640", "3041280", "6082560"]'::jsonb, 2, 'The 10th term corresponds to $r=9$: $\binom{12}{9}(3u)^3\left(\frac{2}{u}\right)^9=220\cdot 27\cdot 512\,u^{-6}=3041280\,u^{-6}$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the coefficient of $x^{13}$ in the 14th term of the expansion of $(3-x)^{15}$?', '["-945", "-105", "105", "945"]'::jsonb, 0, 'The 14th term corresponds to $r=13$: $\binom{15}{13}3^2(-x)^{13}=105\cdot 9\cdot(-x^{13})=-945x^{13}$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the coefficient of $y^{14}$ in the middle term of the expansion of $\left(1-\dfrac{y^2}{2}\right)^{14}$?', '["-3432/16", "-429/16", "429/16", "3432"]'::jsonb, 1, 'With $n=14$, the single middle term corresponds to $r=7$: $\binom{14}{7}\left(-\frac{y^2}{2}\right)^7=3432\cdot\left(-\frac{1}{128}\right)y^{14}=-\frac{429}{16}y^{14}$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the term independent of $x$ in the expansion of $\left(\dfrac{2x}{3}-\dfrac{3}{2x}\right)^6$?', '["-20", "-15", "15", "20"]'::jsonb, 0, 'The general term is $\binom{6}{k}\left(\frac{2x}{3}\right)^{6-k}\left(-\frac{3}{2x}\right)^k$, which is independent of $x$ when $6-2k=0$, i.e. $k=3$: $\binom{6}{3}\left(\frac{2}{3}\right)^3\left(-\frac{3}{2}\right)^3=20\cdot\frac{8}{27}\cdot\left(-\frac{27}{8}\right)=-20$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the simplified form of $(a-1)^4+4(a-1)^3+6(a-1)^2+4(a-1)+1$?', '["$a^4$", "$a^4-1$", "$(a-1)^4$", "$4a^4$"]'::jsonb, 0, 'The expression is exactly the binomial expansion of $[(a-1)+1]^4$, since the coefficients $1,4,6,4,1$ are $\binom{4}{0},\ldots,\binom{4}{4}$. Hence it equals $a^4$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $(2+\sqrt{3})^7-(2-\sqrt{3})^7$?', '["$2911\\sqrt{3}$", "$5822\\sqrt{3}$", "$5822$", "$11644\\sqrt{3}$"]'::jsonb, 1, 'Expanding both seventh powers and subtracting, the terms with even powers of $\sqrt3$ cancel while the odd-power terms double, giving $2\left[\binom{7}{1}2^6\sqrt3+\binom{7}{3}2^4(\sqrt3)^3+\binom{7}{5}2^2(\sqrt3)^5+\binom{7}{7}(\sqrt3)^7\right]=5822\sqrt{3}$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the coefficient of $x^2$ in the expansion of $(x-2)(x+3)(x-5)(x+9)$?', '["-69", "-47", "5", "270"]'::jsonb, 1, 'Multiplying out the four linear factors gives $x^4+5x^3-47x^2-69x+270$, so the coefficient of $x^2$ is $-47$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the constant term in the expansion of $(t+2)(t-1)(t+3)$?', '["-6", "-1", "4", "6"]'::jsonb, 0, 'Multiplying out gives $t^3+4t^2+t-6$, whose constant term is obtained by setting $t=0$ in each factor: $2\cdot(-1)\cdot 3=-6$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the coefficient of $y^3$ in the fourth term of the expansion of $\left(\dfrac{4}{3}+9y\right)^{10}$?', '["81920", "245760", "655360", "1966080"]'::jsonb, 2, 'The fourth term corresponds to $r=3$: $\binom{10}{3}\left(\frac{4}{3}\right)^7(9y)^3=120\cdot\left(\frac{4}{3}\right)^7\cdot 729\,y^3=655360\,y^3$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the term independent of $t$ in the expansion of $\left(\dfrac{3t^2}{2}-\dfrac{1}{3t}\right)^9$?', '["-7/18", "1/18", "7/18", "9/18"]'::jsonb, 2, 'The general term is $\binom{9}{k}\left(\frac{3t^2}{2}\right)^{9-k}\left(-\frac{1}{3t}\right)^k$, whose power of $t$ is $2(9-k)-k=18-3k$. This vanishes when $k=6$, giving $\binom{9}{6}\left(\frac{3}{2}\right)^3\left(-\frac{1}{3}\right)^6=84\cdot\frac{27}{8}\cdot\frac{1}{729}=\frac{7}{18}$.', 'Binomial Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is $12^{\circ}$ expressed in radians, correct to four decimal places?', '["0.1047", "0.2094", "0.3142", "0.4189"]'::jsonb, 1, 'Using $\theta(\text{rad}) = \theta(\text{deg})\times\frac{\pi}{180}$, $12\times\frac{\pi}{180}\approx 0.2094$ rad.', 'Circular Measure', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is $36.75^{\circ}$ expressed in radians, correct to four decimal places?', '["0.5236", "0.6414", "0.7854", "0.9163"]'::jsonb, 1, '$36.75\times\frac{\pi}{180}\approx 0.6414$ rad.', 'Circular Measure', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is $100^{\circ}$ expressed in radians, correct to four decimal places?', '["1.5708", "1.7453", "1.9199", "2.0944"]'::jsonb, 1, '$100\times\frac{\pi}{180}\approx 1.7453$ rad.', 'Circular Measure', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is $22.5^{\circ}$ expressed in radians, correct to four decimal places?', '["0.2618", "0.3491", "0.3927", "0.4363"]'::jsonb, 2, '$22.5\times\frac{\pi}{180}=\frac{\pi}{8}\approx 0.3927$ rad.', 'Circular Measure', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is $555^{\circ}$ expressed in radians, correct to four decimal places?', '["8.7266", "9.2679", "9.6866", "10.4720"]'::jsonb, 2, '$555\times\frac{\pi}{180}\approx 9.6866$ rad (an angle greater than $2\pi$, since $555^{\circ}$ exceeds one full revolution).', 'Circular Measure', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is 3.50 radians expressed in degrees, correct to two decimal places?', '["180.00", "190.99", "200.54", "210.32"]'::jsonb, 2, 'Using $\theta(\text{deg})=\theta(\text{rad})\times\frac{180}{\pi}$, $3.50\times\frac{180}{\pi}\approx 200.54^{\circ}$.', 'Circular Measure', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is 1.15 radians expressed in degrees, correct to two decimal places?', '["55.29", "60.14", "65.89", "70.12"]'::jsonb, 2, '$1.15\times\frac{180}{\pi}\approx 65.89^{\circ}$.', 'Circular Measure', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is $\dfrac{\pi}{24}$ radians expressed in degrees?', '["6.0", "7.5", "9.0", "12.0"]'::jsonb, 1, 'Since $\pi$ rad $=180^{\circ}$, $\frac{\pi}{24}$ rad $=\frac{180}{24}=7.5^{\circ}$.', 'Circular Measure', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is 5.00 radians expressed in degrees, correct to two decimal places?', '["257.83", "270.00", "286.48", "300.15"]'::jsonb, 2, '$5.00\times\frac{180}{\pi}\approx 286.48^{\circ}$.', 'Circular Measure', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is 0.11 radians expressed in degrees, correct to two decimal places?', '["4.15", "6.30", "8.42", "11.00"]'::jsonb, 1, '$0.11\times\frac{180}{\pi}\approx 6.30^{\circ}$.', 'Circular Measure', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'An arc of a circle subtends an angle of $\dfrac{63}{16}$ degrees at the centre, and the radius of the circle is 3200 m. What is the length of the arc, to the nearest metre?', '["176 m", "198 m", "220 m", "241 m"]'::jsonb, 2, 'Converting the angle to radians, $\frac{63}{16}\times\frac{\pi}{180}\approx 0.06872$ rad. Then the arc length is $s=r\theta = 3200\times 0.06872\approx 220$ m.', 'Circular Measure', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A sector is cut from a circle of diameter 24 cm, with the sector''s central angle equal to $30^{\circ}$. What is the perimeter of the sector, correct to two decimal places (take $\pi=3.1416$)?', '["18.28 cm", "24.00 cm", "30.28 cm", "36.57 cm"]'::jsonb, 2, 'The radius is 12 cm, and the arc length is $r\theta = 12\times\frac{\pi}{6}\approx 6.28$ cm. The perimeter of the sector is two radii plus the arc: $12+12+6.28=30.28$ cm.', 'Circular Measure', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A sector of a circle of radius 1.5 m has a central angle of $\dfrac{\pi}{3}$ radians. What is the area of the sector, correct to four decimal places?', '["0.5890 m$^2$", "1.1781 m$^2$", "2.3562 m$^2$", "3.5343 m$^2$"]'::jsonb, 1, 'Using $\mathcal{A}=\frac{1}{2}r^2\theta$, the area is $\frac{1}{2}(1.5)^2\left(\frac{\pi}{3}\right)\approx 1.1781$ m$^2$.', 'Circular Measure', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A sector of a circle of radius 12 cm has a central angle of $30^{\circ}$. What is the area of the sector, correct to two decimal places?', '["18.85 cm$^2$", "24.00 cm$^2$", "37.70 cm$^2$", "45.24 cm$^2$"]'::jsonb, 2, 'Converting $30^{\circ}$ to radians gives $\frac{\pi}{6}$, so the area is $\mathcal{A}=\frac{1}{2}r^2\theta=\frac12(12)^2\left(\frac{\pi}{6}\right)\approx 37.70$ cm$^2$.', 'Circular Measure', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A pendulum of length 16 cm swings from the vertical through a maximum angle of $23^{\circ}$ on either side. What arc length, in centimetres, does the end of the pendulum trace as it swings from one extreme to the other (through an angle of $46^{\circ}$), correct to two decimal places?', '["6.42", "9.16", "12.85", "18.34"]'::jsonb, 2, 'The angle swept, converted to radians, is $46\times\frac{\pi}{180}\approx 0.8029$ rad, so the arc length is $s=r\theta=16\times 0.8029\approx 12.85$ cm (twice the one-sided value of $16\times 23\times\frac{\pi}{180}\approx 6.42$ cm).', 'Circular Measure', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\tan 765^{\circ}$?', '["-1", "0", "1", "$\\sqrt2$"]'::jsonb, 2, 'Since $765^{\circ}=2(360^{\circ})+45^{\circ}$, periodicity gives $\tan765^{\circ}=\tan45^{\circ}=1$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\cos 765^{\circ}$?', '["0", "$\\frac{1}{2}$", "$\\frac{\\sqrt2}{2}$", "1"]'::jsonb, 2, 'Since $765^{\circ}=2(360^{\circ})+45^{\circ}$, $\cos765^{\circ}=\cos45^{\circ}=\frac{\sqrt2}{2}\approx0.7071$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Given that $\sin 35^{\circ}\approx 0.5736$, what is the value of $\sin(-35^{\circ})$?', '["-0.5736", "-0.8192", "0.5736", "0.8192"]'::jsonb, 0, 'Sine is an odd function: $\sin(-\theta)=-\sin\theta$, so $\sin(-35^{\circ})=-0.5736$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Given that $\tan 45^{\circ}=1$, what is the value of $\tan(-765^{\circ})$?', '["-1", "0", "1", "undefined"]'::jsonb, 0, 'Since $765^{\circ}=2(360^{\circ})+45^{\circ}$, $\tan765^{\circ}=\tan45^{\circ}=1$; and since tangent is odd, $\tan(-765^{\circ})=-\tan765^{\circ}=-1$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Given that $\cos 45^{\circ}\approx 0.7071$, what is the value of $\cos(-765^{\circ})$?', '["-0.7071", "0", "0.5000", "0.7071"]'::jsonb, 3, 'Cosine is an even function: $\cos(-\theta)=\cos\theta$. Since $765^{\circ}=2(360^{\circ})+45^{\circ}$, $\cos(-765^{\circ})=\cos45^{\circ}\approx0.7071$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'An acute angle $\theta$ satisfies $\cos\theta = 0.8064$. What is $\theta$, correct to two decimal places?', '["30.25$^{\\circ}$", "36.25$^{\\circ}$", "41.25$^{\\circ}$", "53.75$^{\\circ}$"]'::jsonb, 1, '$\theta=\cos^{-1}(0.8064)\approx 36.25^{\circ}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'An acute angle $\theta$ satisfies $\sin\theta = 0.7781$. What is $\theta$, correct to two decimal places?', '["38.91$^{\\circ}$", "45.00$^{\\circ}$", "51.09$^{\\circ}$", "60.13$^{\\circ}$"]'::jsonb, 2, '$\theta=\sin^{-1}(0.7781)\approx 51.09^{\circ}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\tan(89.42^{\circ})$, correct to two decimal places?', '["1.00", "57.29", "98.78", "572.90"]'::jsonb, 2, 'As $\theta$ approaches $90^{\circ}$, $\tan\theta$ increases very rapidly; direct calculation gives $\tan(89.42^{\circ})\approx 98.78$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If an acute angle has sine equal to 0.1822, what is the secant of its complement?', '["1.822", "3.216", "5.017", "5.488"]'::jsonb, 3, 'By the complementary angle property, the secant of the complement of an angle equals the cosecant of the angle itself: $\sec(90^{\circ}-\alpha)=\csc\alpha=1/\sin\alpha=1/0.1822\approx 5.488$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Given that $\sin69.5^{\circ}\approx 0.9367$, what is the value of $\sin 110.5^{\circ}$?', '["-0.9367", "0.3502", "0.9367", "1.0633"]'::jsonb, 2, 'Since $110.5^{\circ}$ and $69.5^{\circ}$ are supplementary, $\sin 110.5^{\circ}=\sin(180^{\circ}-110.5^{\circ})=\sin69.5^{\circ}\approx0.9367$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Given that $\tan 21.7^{\circ}\approx 0.3979$, what is the value of $\cot 158.3^{\circ}$, correct to four decimal places?', '["-2.5129", "-0.3979", "0.3979", "2.5129"]'::jsonb, 0, 'Since $158.3^{\circ}=180^{\circ}-21.7^{\circ}$, the supplementary angle property gives $\tan158.3^{\circ}=-\tan21.7^{\circ}$, and so $\cot158.3^{\circ}=-\cot21.7^{\circ}=-1/0.3979\approx-2.5129$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\sec(205.42^{\circ})$, correct to four decimal places?', '["-1.1072", "-0.9032", "0.9032", "1.1072"]'::jsonb, 0, 'Since $205.42^{\circ}$ lies $25.42^{\circ}$ past $180^{\circ}$, the reflexive angle property gives $\cos205.42^{\circ}=-\cos25.42^{\circ}\approx-0.9032$, so $\sec205.42^{\circ}\approx-1.1072$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\tan 275^{\circ}$, correct to two decimal places?', '["-11.43", "-1.43", "1.43", "11.43"]'::jsonb, 0, 'Since $275^{\circ}=360^{\circ}-85^{\circ}$, $\tan275^{\circ}=-\tan85^{\circ}\approx-11.43$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\cos 275^{\circ}$, correct to four decimal places?', '["-0.9962", "-0.0872", "0.0872", "0.9962"]'::jsonb, 2, 'Since $275^{\circ}=360^{\circ}-85^{\circ}$, $\cos275^{\circ}=\cos85^{\circ}\approx0.0872$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\sec 995^{\circ}$, correct to two decimal places?', '["-11.47", "1.15", "8.72", "11.47"]'::jsonb, 3, 'Since $995^{\circ}=2(360^{\circ})+275^{\circ}$, periodicity gives $\sec995^{\circ}=\sec275^{\circ}=1/\cos275^{\circ}\approx 1/0.0872\approx11.47$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are the two solutions of $\sin\theta = 0.5329$ in the interval $0^{\circ}\le\theta<360^{\circ}$, correct to one decimal place?', '["$32.2^{\\circ}$ and $147.8^{\\circ}$", "$32.2^{\\circ}$ and $212.2^{\\circ}$", "$57.8^{\\circ}$ and $122.2^{\\circ}$", "$147.8^{\\circ}$ and $327.8^{\\circ}$"]'::jsonb, 0, 'Since the sine is positive, the solutions lie in quadrants I and II: $\theta=\sin^{-1}(0.5329)\approx32.2^{\circ}$, and the quadrant II solution is $180^{\circ}-32.2^{\circ}=147.8^{\circ}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are the two solutions of $\cos\theta = -0.7133$ in the interval $0^{\circ}\le\theta<360^{\circ}$, correct to one decimal place?', '["$44.5^{\\circ}$ and $315.5^{\\circ}$", "$135.5^{\\circ}$ and $224.5^{\\circ}$", "$135.5^{\\circ}$ and $315.5^{\\circ}$", "$224.5^{\\circ}$ and $335.5^{\\circ}$"]'::jsonb, 1, 'Since the cosine is negative, the solutions lie in quadrants II and III. The reference angle is $\cos^{-1}(0.7133)\approx44.5^{\circ}$, giving $\theta=180^{\circ}-44.5^{\circ}=135.5^{\circ}$ and $\theta=180^{\circ}+44.5^{\circ}=224.5^{\circ}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the only solution of $\sin\theta=-1$ in the interval $0^{\circ}\le\theta<360^{\circ}$?', '["$90^{\\circ}$", "$180^{\\circ}$", "$270^{\\circ}$", "$360^{\\circ}$"]'::jsonb, 2, 'The sine function attains its minimum value of $-1$ only at $\theta=270^{\circ}$ within one revolution.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'How many real solutions does the equation $\sec\theta=\dfrac{1}{2}$ have?', '["exactly one", "exactly two", "infinitely many", "none"]'::jsonb, 3, 'Since $\sec\theta=1/\cos\theta$ and $|\cos\theta|\le1$ always, $|\sec\theta|\ge1$ for every angle where it is defined. Because $\frac12<1$, the equation has no solution.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A point $P$ lies 8 units from the origin, along the terminal line of an angle of $155^{\circ}$ in standard position. What is the $x$-coordinate of $P$, correct to two decimal places?', '["-7.25", "-3.38", "3.38", "7.25"]'::jsonb, 0, '$x=8\cos155^{\circ}\approx8(-0.9063)\approx-7.25$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A point $P$ lies 8 units from the origin, along the terminal line of an angle of $155^{\circ}$ in standard position. What is the $y$-coordinate of $P$, correct to two decimal places?', '["-3.38", "3.38", "7.25", "8.00"]'::jsonb, 1, '$y=8\sin155^{\circ}\approx8(0.4226)\approx3.38$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A right circular cone has height 1.5 m and slant height 2.5 m. What is its vertical (apex) angle, correct to two decimal places?', '["36.87$^{\\circ}$", "53.13$^{\\circ}$", "73.74$^{\\circ}$", "106.26$^{\\circ}$"]'::jsonb, 3, 'The half-angle $\theta$ satisfies $\cos\theta=1.5/2.5=0.6$, giving $\theta\approx53.13^{\circ}$. The full vertical angle is twice this, $\approx106.26^{\circ}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A motor boat crosses a 60-metre-wide canal along a path inclined at $55^{\circ}$ to the bank, travelling at a steady speed of 20 km/hr. How long, in seconds, does the crossing take, correct to one decimal place?', '["10.8 s", "13.2 s", "15.6 s", "18.9 s"]'::jsonb, 1, 'The path length is $r=60/\sin55^{\circ}\approx73.25$ m. At $20\,000$ m/hr, the time taken is $73.25/20000\approx0.003662$ hr, i.e. about $13.2$ seconds.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'An acute angle has sine equal to 0.8. What is the tangent of this angle?', '["$3/4$", "$4/3$", "$3/5$", "$4/5$"]'::jsonb, 1, 'If $\sin\theta=0.8=4/5$, then by the Pythagorean relation $\cos\theta=\sqrt{1-0.64}=0.6=3/5$, so $\tan\theta=\sin\theta/\cos\theta=(4/5)/(3/5)=4/3$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'An observer standing 120 m from the foot of a tower measures the angle of elevation of the top of the tower as $35^{\circ}$. What is the height of the tower, correct to two decimal places?', '["68.76 m", "84.02 m", "97.35 m", "146.49 m"]'::jsonb, 1, 'If $PQ$ is the height, then $\tan35^{\circ}=PQ/120$, so $PQ=120\tan35^{\circ}\approx84.02$ m.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'From the top of an 84.02 m tower, the angle of depression of a milestone on the ground on the far side of the tower''s base is $40^{\circ}$. What is the distance from the tower''s base to the milestone, correct to two decimal places?', '["70.51 m", "84.02 m", "100.14 m", "130.72 m"]'::jsonb, 2, 'The angle of depression equals the angle of elevation from the milestone, so $\tan40^{\circ}=84.02/d$, giving $d=84.02/\tan40^{\circ}\approx100.14$ m.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'In a right triangle, one leg is 120 units long and the angle between this leg and the hypotenuse is $35^{\circ}$. What is the length of the hypotenuse, correct to two decimal places?', '["68.76", "84.02", "146.49", "209.13"]'::jsonb, 2, 'If the leg of 120 units is adjacent to the $35^{\circ}$ angle, then the hypotenuse is $120\sec35^{\circ}=120/\cos35^{\circ}\approx146.49$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A 10-foot ladder rests against a wall with its foot 8 feet from the wall. What angle, correct to two decimal places, does the ladder make with the ground?', '["30.00$^{\\circ}$", "36.87$^{\\circ}$", "45.00$^{\\circ}$", "53.13$^{\\circ}$"]'::jsonb, 1, 'The angle $\theta$ between the ladder and the ground satisfies $\cos\theta=8/10=0.8$, so $\theta=\cos^{-1}(0.8)\approx36.87^{\circ}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A 10-foot ladder rests against a wall with its foot 8 feet from the wall. How high up the wall does the ladder reach?', '["6 ft", "6.4 ft", "7.2 ft", "8 ft"]'::jsonb, 0, 'By the Pythagorean theorem, the height is $\sqrt{10^2-8^2}=\sqrt{36}=6$ ft.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A line segment joins the points $(2,0)$ and $(5,0)$. What is the length of the projection of this segment onto a line that makes an angle of $45^{\circ}$ with it, correct to two decimal places?', '["1.50", "2.12", "2.60", "3.00"]'::jsonb, 1, 'The segment has length 3, and the length of its projection onto another line equals (length)$\times\cos\theta$, where $\theta$ is the angle between them: $3\cos45^{\circ}=\frac{3\sqrt2}{2}\approx2.12$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A line segment 33 cm long is inclined at $60.75^{\circ}$ to the positive $x$-axis. What is the length of its projection onto the $y$-axis, correct to two decimal places?', '["16.15 cm", "16.90 cm", "28.79 cm", "32.29 cm"]'::jsonb, 2, 'The angle between the segment and the $y$-axis is $90^{\circ}-60.75^{\circ}=29.25^{\circ}$, so the projection has length $33\cos29.25^{\circ}\approx28.79$ cm.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'An angle $\theta$ in standard position has its terminal line passing through the point $(-5,12)$. What is $\sin\theta$?', '["-12/13", "-5/13", "5/13", "12/13"]'::jsonb, 3, 'The distance from the origin is $r=\sqrt{(-5)^2+12^2}=13$, so $\sin\theta=y/r=12/13$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'An angle $\theta$ in standard position has its terminal line passing through the point $(-5,12)$. What is $\cos\theta$?', '["-5/13", "-12/13", "5/13", "12/13"]'::jsonb, 0, 'The distance from the origin is $r=\sqrt{(-5)^2+12^2}=13$, so $\cos\theta=x/r=-5/13$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'An angle $\theta$ in standard position has its terminal line passing through the point $(-5,12)$. What is $\tan\theta$?', '["-12/5", "-5/12", "5/12", "12/5"]'::jsonb, 0, '$\tan\theta=y/x=12/(-5)=-12/5$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A parallelogram has two adjacent sides of length 5 cm and 3 cm, with an included angle of $\dfrac{2\pi}{3}$ radians. What is its area, correct to two decimal places?', '["7.50 cm$^2$", "12.99 cm$^2$", "15.00 cm$^2$", "25.98 cm$^2$"]'::jsonb, 1, 'The area of a parallelogram with adjacent sides $a,b$ and included angle $\theta$ is $ab\sin\theta$. Here this is $5\times3\times\sin\frac{2\pi}{3}=15\times\frac{\sqrt3}{2}\approx12.99$ cm$^2$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'An acute angle has cosine equal to 0.9255. What is the angle, correct to two decimal places?', '["17.75$^{\\circ}$", "22.26$^{\\circ}$", "27.85$^{\\circ}$", "32.10$^{\\circ}$"]'::jsonb, 1, '$\theta=\cos^{-1}(0.9255)\approx22.26^{\circ}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'An acute angle has tangent equal to 0.8406. What is the angle, correct to two decimal places?', '["32.66$^{\\circ}$", "40.05$^{\\circ}$", "46.98$^{\\circ}$", "50.00$^{\\circ}$"]'::jsonb, 1, '$\theta=\tan^{-1}(0.8406)\approx40.05^{\circ}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'An acute angle has sine equal to 0.8221. What is the angle, correct to two decimal places?', '["45.00$^{\\circ}$", "50.62$^{\\circ}$", "55.30$^{\\circ}$", "60.15$^{\\circ}$"]'::jsonb, 2, '$\theta=\sin^{-1}(0.8221)\approx55.30^{\circ}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'An acute angle has cotangent equal to 0.4834. What is the angle, correct to two decimal places?', '["25.80$^{\\circ}$", "45.79$^{\\circ}$", "58.06$^{\\circ}$", "64.20$^{\\circ}$"]'::jsonb, 3, 'Since $\cot\theta=0.4834$, $\tan\theta=1/0.4834\approx2.0687$, so $\theta=\tan^{-1}(2.0687)\approx64.20^{\circ}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'An acute angle has secant equal to 2.4588. What is the angle, correct to two decimal places?', '["24.00$^{\\circ}$", "59.53$^{\\circ}$", "66.00$^{\\circ}$", "70.42$^{\\circ}$"]'::jsonb, 2, 'Since $\sec\theta=2.4588$, $\cos\theta=1/2.4588\approx0.4067$, so $\theta=\cos^{-1}(0.4067)\approx66.00^{\circ}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'An acute angle has cosecant equal to 5.7604. What is the angle, correct to two decimal places?', '["9.71$^{\\circ}$", "10.00$^{\\circ}$", "17.35$^{\\circ}$", "80.29$^{\\circ}$"]'::jsonb, 1, 'Since $\csc\theta=5.7604$, $\sin\theta=1/5.7604\approx0.1736$, so $\theta=\sin^{-1}(0.1736)\approx10.00^{\circ}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A right circular cone has slant height 15 cm and base diameter 24 cm. What is its height?', '["8 cm", "9 cm", "10 cm", "12 cm"]'::jsonb, 1, 'The height, radius, and slant height form a right triangle with hypotenuse 15 and one leg equal to the radius, 12. The height is $\sqrt{15^2-12^2}=\sqrt{81}=9$ cm.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A right circular cone has slant height 15 cm and base diameter 24 cm. What is its vertical (apex) angle, correct to two decimal places?', '["53.13$^{\\circ}$", "73.74$^{\\circ}$", "90.00$^{\\circ}$", "106.26$^{\\circ}$"]'::jsonb, 3, 'The half-angle $\beta$ satisfies $\sin\beta=12/15=0.8$, so $\beta\approx53.13^{\circ}$, and the full vertical angle is $2\beta\approx106.26^{\circ}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are the two solutions of $\sin\theta=0.4305$ in the interval $0^{\circ}\le\theta<360^{\circ}$, correct to two decimal places?', '["$25.50^{\\circ}$ and $154.50^{\\circ}$", "$25.50^{\\circ}$ and $205.50^{\\circ}$", "$64.50^{\\circ}$ and $115.50^{\\circ}$", "$154.50^{\\circ}$ and $334.50^{\\circ}$"]'::jsonb, 0, 'Since sine is positive, the reference angle is $\sin^{-1}(0.4305)\approx25.50^{\circ}$, giving the quadrant I solution $25.50^{\circ}$ and the quadrant II solution $180^{\circ}-25.50^{\circ}=154.50^{\circ}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are the two solutions of $\cos\theta=-0.3338$ in the interval $0^{\circ}\le\theta<360^{\circ}$, correct to two decimal places?', '["$70.50^{\\circ}$ and $289.50^{\\circ}$", "$109.50^{\\circ}$ and $250.50^{\\circ}$", "$109.50^{\\circ}$ and $289.50^{\\circ}$", "$180.00^{\\circ}$ and $250.50^{\\circ}$"]'::jsonb, 1, 'The reference angle is $\cos^{-1}(0.3338)\approx70.50^{\circ}$. Since cosine is negative, the solutions lie in quadrants II and III: $180^{\circ}-70.50^{\circ}=109.50^{\circ}$ and $180^{\circ}+70.50^{\circ}=250.50^{\circ}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A vertical flagpole 25 m tall casts a horizontal shadow 15 m long on level ground. What is the angle of elevation of the sun, correct to two decimal places?', '["30.96$^{\\circ}$", "36.87$^{\\circ}$", "53.13$^{\\circ}$", "59.04$^{\\circ}$"]'::jsonb, 3, 'The angle of elevation $\theta$ satisfies $\tan\theta=25/15$, so $\theta=\tan^{-1}(25/15)\approx59.04^{\circ}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A pendulum of length 16 cm swings from the vertical through a maximum angle of $23^{\circ}$. What is the maximum vertical height, correct to two decimal places, through which the end of the pendulum rises above its lowest point?', '["0.64 cm", "1.27 cm", "2.55 cm", "6.42 cm"]'::jsonb, 1, 'If the pendulum hangs vertically with its end at the lowest point, swinging out to angle $23^{\circ}$ raises the end by $L-L\cos23^{\circ}=16(1-\cos23^{\circ})\approx1.27$ cm.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\tan\dfrac{5\pi}{6}$?', '["$-\\sqrt3$", "$-\\dfrac{\\sqrt3}{3}$", "$\\dfrac{\\sqrt3}{3}$", "$\\sqrt3$"]'::jsonb, 1, 'Since $\frac{5\pi}{6}=\pi-\frac{\pi}{6}$, $\tan\frac{5\pi}{6}=-\tan\frac{\pi}{6}=-\frac{\sqrt3}{3}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\sin\dfrac{5\pi}{4}$?', '["$-\\dfrac{\\sqrt2}{2}$", "$-\\dfrac{1}{2}$", "$\\dfrac{1}{2}$", "$\\dfrac{\\sqrt2}{2}$"]'::jsonb, 0, 'Since $\frac{5\pi}{4}=\pi+\frac{\pi}{4}$, this angle lies in quadrant III, where sine is negative: $\sin\frac{5\pi}{4}=-\sin\frac{\pi}{4}=-\frac{\sqrt2}{2}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\cos\dfrac{9\pi}{2}$?', '["-1", "0", "$\\dfrac{1}{2}$", "1"]'::jsonb, 1, 'Since $\frac{9\pi}{2}=4\pi+\frac{\pi}{2}$, periodicity gives $\cos\frac{9\pi}{2}=\cos\frac{\pi}{2}=0$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\cos\dfrac{11\pi}{6}$?', '["$-\\dfrac{\\sqrt3}{2}$", "$-\\dfrac{1}{2}$", "$\\dfrac{1}{2}$", "$\\dfrac{\\sqrt3}{2}$"]'::jsonb, 3, 'Since $\frac{11\pi}{6}=2\pi-\frac{\pi}{6}$, $\cos\frac{11\pi}{6}=\cos\frac{\pi}{6}=\frac{\sqrt3}{2}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\cot\dfrac{7\pi}{4}$?', '["-1", "$-\\sqrt3$", "0", "1"]'::jsonb, 0, 'Since $\frac{7\pi}{4}=2\pi-\frac{\pi}{4}$, this lies in quadrant IV, where $\tan\frac{7\pi}{4}=-\tan\frac{\pi}{4}=-1$, so $\cot\frac{7\pi}{4}=-1$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\sec(2280^{\circ})$?', '["-2", "$-\\dfrac{2\\sqrt3}{3}$", "$\\dfrac{2\\sqrt3}{3}$", "2"]'::jsonb, 0, 'Subtracting complete revolutions, $2280^{\circ}-6(360^{\circ})=120^{\circ}$. Since $\cos120^{\circ}=-\frac{1}{2}$, $\sec(2280^{\circ})=\sec120^{\circ}=-2$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the exact value of $\sin75^\circ$?', '["$\\dfrac{\\sqrt6+\\sqrt2}{4}$", "$\\dfrac{\\sqrt6-\\sqrt2}{4}$", "$\\dfrac{\\sqrt2+\\sqrt3}{2}$", "$\\dfrac{\\sqrt3+1}{4}$"]'::jsonb, 0, 'Writing $75^\circ=45^\circ+30^\circ$ and applying the sine addition formula gives $\sin45^\circ\cos30^\circ+\cos45^\circ\sin30^\circ=\dfrac{\sqrt2}{2}\cdot\dfrac{\sqrt3}{2}+\dfrac{\sqrt2}{2}\cdot\dfrac12=\dfrac{\sqrt6+\sqrt2}{4}$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the exact value of $\sec75^\circ$?', '["$\\sqrt6+\\sqrt2$", "$\\sqrt6-\\sqrt2$", "$2-\\sqrt3$", "$\\dfrac{4}{\\sqrt6+\\sqrt2}$ simplified to $\\sqrt6-\\sqrt2$"]'::jsonb, 0, 'Since $\cos75^\circ=\dfrac{\sqrt6-\sqrt2}{4}$, its reciprocal is $\dfrac{4}{\sqrt6-\sqrt2}$, which rationalizes to $\sqrt6+\sqrt2$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the exact value of $\cot75^\circ$?', '["$2-\\sqrt3$", "$2+\\sqrt3$", "$\\sqrt3-1$", "$\\dfrac{1}{\\sqrt3}$"]'::jsonb, 0, 'Using $75^\circ=45^\circ+30^\circ$ with the tangent addition formula, $\tan75^\circ=\dfrac{1+\frac{1}{\sqrt3}}{1-\frac{1}{\sqrt3}}=2+\sqrt3$, so $\cot75^\circ=\dfrac{1}{2+\sqrt3}=2-\sqrt3$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the exact value of $\tan105^\circ$?', '["$-2-\\sqrt3$", "$2+\\sqrt3$", "$-2+\\sqrt3$", "$-\\sqrt3$"]'::jsonb, 0, 'Writing $105^\circ=60^\circ+45^\circ$ and applying the tangent addition formula: $\tan105^\circ=\dfrac{\sqrt3+1}{1-\sqrt3\cdot1}=\dfrac{\sqrt3+1}{1-\sqrt3}$, which simplifies to $-2-\sqrt3$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the exact value of $\sin135^\circ$?', '["$\\dfrac{\\sqrt2}{2}$", "$-\\dfrac{\\sqrt2}{2}$", "$\\dfrac12$", "$\\dfrac{\\sqrt3}{2}$"]'::jsonb, 0, '$135^\circ$ lies in the second quadrant where sine is positive, and its reference angle is $45^\circ$, so $\sin135^\circ=\sin45^\circ=\dfrac{\sqrt2}{2}$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the exact value of $\text{cosec}\,120^\circ$?', '["$\\dfrac{2\\sqrt3}{3}$", "$\\dfrac{\\sqrt3}{2}$", "$-\\dfrac{2\\sqrt3}{3}$", "$2$"]'::jsonb, 0, '$\sin120^\circ=\dfrac{\sqrt3}{2}$, so $\text{cosec}\,120^\circ=\dfrac{2}{\sqrt3}=\dfrac{2\sqrt3}{3}$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the exact value of $\cos150^\circ$?', '["$-\\dfrac{\\sqrt3}{2}$", "$\\dfrac{\\sqrt3}{2}$", "$-\\dfrac12$", "$-\\dfrac{\\sqrt2}{2}$"]'::jsonb, 0, '$150^\circ$ lies in the second quadrant where cosine is negative, with reference angle $30^\circ$, so $\cos150^\circ=-\cos30^\circ=-\dfrac{\sqrt3}{2}$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\sin\theta=\dfrac35$ and $\sin\psi=\dfrac{12}{13}$, with $\theta$ and $\psi$ both acute, what is $\sin(\theta+\psi)$?', '["$\\dfrac{63}{65}$", "$\\dfrac{33}{65}$", "$\\dfrac{56}{65}$", "$\\dfrac{16}{65}$"]'::jsonb, 0, 'With both angles acute, $\cos\theta=\frac45$ and $\cos\psi=\frac{5}{13}$. Then $\sin(\theta+\psi)=\sin\theta\cos\psi+\cos\theta\sin\psi=\frac35\cdot\frac{5}{13}+\frac45\cdot\frac{12}{13}=\dfrac{63}{65}$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\sin\theta=\dfrac35$ with $\theta$ acute, and $\sin\psi=\dfrac{12}{13}$ with $\psi$ obtuse, what is $\sin(\theta+\psi)$?', '["$\\dfrac{33}{65}$", "$\\dfrac{63}{65}$", "$-\\dfrac{33}{65}$", "$\\dfrac{16}{65}$"]'::jsonb, 0, 'Since $\psi$ is obtuse, $\cos\psi=-\frac{5}{13}$ while $\cos\theta=\frac45$ (still acute). Then $\sin(\theta+\psi)=\frac35\cdot\left(-\frac{5}{13}\right)+\frac45\cdot\frac{12}{13}=\dfrac{33}{65}$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\sin\psi=\dfrac45$ and $\psi$ is acute, what is $\tan2\psi$?', '["$-\\dfrac{24}{7}$", "$\\dfrac{24}{7}$", "$-\\dfrac{7}{24}$", "$\\dfrac{7}{24}$"]'::jsonb, 0, 'Since $\psi$ is acute, $\cos\psi=\frac35$ and $\tan\psi=\frac43$. Then $\tan2\psi=\dfrac{2\tan\psi}{1-\tan^2\psi}=\dfrac{8/3}{1-16/9}=\dfrac{8/3}{-7/9}=-\dfrac{24}{7}$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'The expression $15\sin\theta+8\cos\theta$ can be written as $R\sin(\theta+\alpha)$. What is $R$?', '["$17$", "$23$", "$7$", "$\\sqrt{15}$"]'::jsonb, 0, '$R=\sqrt{15^2+8^2}=\sqrt{225+64}=\sqrt{289}=17$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'The expression $\sin\theta-\sqrt3\cos\theta$ can be written as $R\sin(\theta+\alpha)$ with $|\alpha|\le180^\circ$. What are $R$ and $\alpha$?', '["$R=2,\\ \\alpha=-60^\\circ$", "$R=2,\\ \\alpha=60^\\circ$", "$R=4,\\ \\alpha=-60^\\circ$", "$R=2,\\ \\alpha=-30^\\circ$"]'::jsonb, 0, '$R=\sqrt{1^2+(\sqrt3)^2}=2$, and matching $\sin\theta-\sqrt3\cos\theta$ with $R\sin\theta\cos\alpha+R\cos\theta\sin\alpha$ gives $\cos\alpha=\frac12,\ \sin\alpha=-\frac{\sqrt3}{2}$, so $\alpha=-60^\circ$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the exact value of $\sin15^\circ\cos75^\circ$?', '["$\\dfrac{2-\\sqrt3}{4}$", "$\\dfrac{2+\\sqrt3}{4}$", "$\\dfrac{\\sqrt3}{4}$", "$\\dfrac{1}{4}$"]'::jsonb, 0, 'Using the product formula $\sin A\cos B=\tfrac12[\sin(A+B)+\sin(A-B)]$ with $A=15^\circ,B=75^\circ$: $\tfrac12[\sin90^\circ+\sin(-60^\circ)]=\tfrac12\left(1-\dfrac{\sqrt3}{2}\right)=\dfrac{2-\sqrt3}{4}$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the exact value of $\sin75^\circ+\sin15^\circ$?', '["$\\dfrac{\\sqrt6}{2}$", "$\\sqrt6$", "$\\dfrac{\\sqrt2+\\sqrt3}{2}$", "$1$"]'::jsonb, 0, 'Using the sum-to-product formula $\sin x+\sin y=2\sin\frac{x+y}{2}\cos\frac{x-y}{2}$ with $x=75^\circ,y=15^\circ$: $2\sin45^\circ\cos30^\circ=2\cdot\dfrac{\sqrt2}{2}\cdot\dfrac{\sqrt3}{2}=\dfrac{\sqrt6}{2}$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the exact value of $\cos127.5^\circ\cos(-7.5^\circ)$?', '["$-\\dfrac{1+\\sqrt2}{4}$", "$\\dfrac{1+\\sqrt2}{4}$", "$-\\dfrac{\\sqrt2}{4}$", "$-\\dfrac{1-\\sqrt2}{4}$"]'::jsonb, 0, 'Using $\cos A\cos B=\tfrac12[\cos(A-B)+\cos(A+B)]$ with $A=127.5^\circ,B=-7.5^\circ$: $\tfrac12[\cos135^\circ+\cos120^\circ]=\tfrac12\left(-\dfrac{\sqrt2}{2}-\dfrac12\right)=-\dfrac{1+\sqrt2}{4}$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the exact value of $\tan\dfrac{13\pi}{12}$?', '["$2-\\sqrt3$", "$2+\\sqrt3$", "$-(2-\\sqrt3)$", "$\\sqrt3-1$"]'::jsonb, 0, '$\dfrac{13\pi}{12}=\pi+\dfrac{\pi}{12}$, and since tangent has period $\pi$, $\tan\dfrac{13\pi}{12}=\tan\dfrac{\pi}{12}=\tan15^\circ=2-\sqrt3$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the exact value of $\cot292.5^\circ$?', '["$1-\\sqrt2$", "$\\sqrt2-1$", "$-1-\\sqrt2$", "$1+\\sqrt2$"]'::jsonb, 0, '$292.5^\circ=360^\circ-67.5^\circ$, so $\cot292.5^\circ=-\cot67.5^\circ$. Since $\tan67.5^\circ=\tan(45^\circ+22.5^\circ)=1+\sqrt2$, $\cot67.5^\circ=\sqrt2-1$, giving $\cot292.5^\circ=1-\sqrt2$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the exact value of $\text{Arctan}\dfrac12+\text{Arctan}\dfrac13$?', '["$\\dfrac{\\pi}{4}$", "$\\dfrac{\\pi}{3}$", "$\\dfrac{\\pi}{6}$", "$\\dfrac{\\pi}{2}$"]'::jsonb, 0, 'By the tangent addition formula, $\tan\!\left(\text{Arctan}\frac12+\text{Arctan}\frac13\right)=\dfrac{\frac12+\frac13}{1-\frac12\cdot\frac13}=\dfrac{5/6}{5/6}=1$, and since both angles are small and positive, their sum is $\dfrac{\pi}{4}$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Given that $\sin\phi=\dfrac{15}{17}$ with $\cos\phi<0$, and $\cos\theta=-\dfrac{12}{13}$ with $\tan\theta<0$, what is $\sin(\theta+\phi)$?', '["$-\\dfrac{220}{221}$", "$\\dfrac{220}{221}$", "$-\\dfrac{171}{221}$", "$\\dfrac{171}{221}$"]'::jsonb, 0, 'Since $\cos\theta<0$ and $\tan\theta<0$, $\theta$ is in the second quadrant, so $\sin\theta=\frac{5}{13}$. Since $\sin\phi>0$ and $\cos\phi<0$, $\phi$ is also in the second quadrant, so $\cos\phi=-\frac{8}{17}$. Then $\sin(\theta+\phi)=\sin\theta\cos\phi+\cos\theta\sin\phi=\frac{5}{13}\left(-\frac{8}{17}\right)+\left(-\frac{12}{13}\right)\frac{15}{17}=-\dfrac{220}{221}$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are the solutions of $\dfrac12\cos\theta-\dfrac{\sqrt3}{2}\sin\theta=\dfrac12$ for $\theta$ in $[0,2\pi)$?', '["$0$ and $\\dfrac{4\\pi}{3}$", "$0$ and $\\dfrac{2\\pi}{3}$", "$\\dfrac{\\pi}{3}$ and $\\dfrac{4\\pi}{3}$", "$0$ only"]'::jsonb, 0, 'The left side equals $\cos\!\left(\theta+\frac{\pi}{3}\right)$, so the equation becomes $\cos\!\left(\theta+\frac{\pi}{3}\right)=\frac12$, giving $\theta+\frac{\pi}{3}=\pm\frac{\pi}{3}+2k\pi$. This yields $\theta=0$ or $\theta=-\frac{2\pi}{3}\equiv\frac{4\pi}{3}$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the exact value of $\cos75^\circ-\cos15^\circ$?', '["$-\\dfrac{\\sqrt2}{2}$", "$\\dfrac{\\sqrt2}{2}$", "$-\\dfrac{\\sqrt3}{2}$", "$-1$"]'::jsonb, 0, 'Using $\cos x-\cos y=-2\sin\frac{x+y}{2}\sin\frac{x-y}{2}$ with $x=75^\circ,y=15^\circ$: $-2\sin45^\circ\sin30^\circ=-2\cdot\dfrac{\sqrt2}{2}\cdot\dfrac12=-\dfrac{\sqrt2}{2}$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the exact value of $\sin52.5^\circ\cos7.5^\circ$?', '["$\\dfrac{\\sqrt3+\\sqrt2}{4}$", "$\\dfrac{\\sqrt3-\\sqrt2}{4}$", "$\\dfrac{\\sqrt6+\\sqrt2}{4}$", "$\\dfrac12$"]'::jsonb, 0, 'Using $\sin A\cos B=\tfrac12[\sin(A+B)+\sin(A-B)]$ with $A=52.5^\circ,B=7.5^\circ$: $\tfrac12[\sin60^\circ+\sin45^\circ]=\tfrac12\left(\dfrac{\sqrt3}{2}+\dfrac{\sqrt2}{2}\right)=\dfrac{\sqrt3+\sqrt2}{4}$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the exact value of $2\cos\dfrac{\pi}{12}\cos\dfrac{\pi}{4}$?', '["$\\dfrac{\\sqrt3+1}{2}$", "$\\dfrac{\\sqrt3-1}{2}$", "$\\sqrt3$", "$\\dfrac{\\sqrt2+1}{2}$"]'::jsonb, 0, 'Using $2\cos A\cos B=\cos(A-B)+\cos(A+B)$ with $A=\frac{\pi}{12},B=\frac{\pi}{4}$: $\cos\!\left(-\frac{\pi}{6}\right)+\cos\frac{\pi}{3}=\dfrac{\sqrt3}{2}+\dfrac12=\dfrac{\sqrt3+1}{2}$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the exact value of $\sin135^\circ\sin15^\circ$?', '["$\\dfrac{\\sqrt3-1}{4}$", "$\\dfrac{\\sqrt3+1}{4}$", "$-\\dfrac{\\sqrt3-1}{4}$", "$\\dfrac14$"]'::jsonb, 0, 'Using $\sin A\sin B=\tfrac12[\cos(A-B)-\cos(A+B)]$ with $A=135^\circ,B=15^\circ$: $\tfrac12[\cos120^\circ-\cos150^\circ]=\tfrac12\left(-\dfrac12+\dfrac{\sqrt3}{2}\right)=\dfrac{\sqrt3-1}{4}$.', 'Addition and Factor Formulae', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Points $A$ and $B$ on the Argand plane represent the complex numbers $3+3i$ and $5+4i$ respectively. What is the distance $|AB|$?', '["$\\sqrt5$", "$5$", "$\\sqrt2$", "$3$"]'::jsonb, 0, '$|AB|=|(3+3i)-(5+4i)|=|-2-i|=\sqrt{(-2)^2+(-1)^2}=\sqrt5$.', 'Argand Diagram', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $|z-1+i|$ is a nonzero constant, what curve does the point representing $z$ trace on the Argand plane?', '["A circle centred at $(1,-1)$", "A circle centred at $(-1,1)$", "A straight line through $(1,-1)$", "A circle centred at the origin"]'::jsonb, 0, '$|z-(1-i)|=$ constant means the distance from $z$ to the fixed point $1-i$, i.e. the point $(1,-1)$, is constant, which describes a circle centred at $(1,-1)$.', 'Argand Diagram', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Points representing $1+5i$, $2+i$, and $5+4i$ on the Argand plane form a triangle. Which two sides of this triangle are equal in length?', '["The sides joining $1+5i$ to $2+i$, and $1+5i$ to $5+4i$, both of length $\\sqrt{17}$", "The sides joining $2+i$ to $5+4i$, and $1+5i$ to $5+4i$, both of length $3\\sqrt2$", "All three sides are equal", "No two sides are equal"]'::jsonb, 0, 'The three side lengths are $|(1+5i)-(2+i)|=|-1+4i|=\sqrt{17}$, $|(2+i)-(5+4i)|=|-3-3i|=3\sqrt2$, and $|(1+5i)-(5+4i)|=|-4+i|=\sqrt{17}$. The first and third are equal, so the triangle is isosceles with those two equal sides.', 'Argand Diagram', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Points $A$ and $B$ on the Argand plane represent the complex numbers $2+i$ and $-3i$ respectively. What is $|AB|$?', '["$2\\sqrt5$", "$\\sqrt5$", "$2\\sqrt2$", "$5$"]'::jsonb, 0, '$|AB|=|(2+i)-(-3i)|=|2+4i|=\sqrt{2^2+4^2}=\sqrt{20}=2\sqrt5$.', 'Argand Diagram', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Points $B$ and $C$ on the Argand plane represent the complex numbers $5+4i$ and $4+5i$ respectively. What is the distance $|BC|$?', '["$\\sqrt2$", "$2$", "$1$", "$\\sqrt5$"]'::jsonb, 0, '$|BC|=|(5+4i)-(4+5i)|=|1-i|=\sqrt{1^2+(-1)^2}=\sqrt2$.', 'Argand Diagram', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the period of the function $\sin(3\theta)$?', '["$\\dfrac{2\\pi}{3}$", "$2\\pi$", "$\\pi$", "$3\\pi$"]'::jsonb, 0, 'For $\sin(k\theta)$ the period is $\dfrac{2\pi}{k}$. With $k=3$, the period is $\dfrac{2\pi}{3}$.', 'Circular Measure', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the period of the function $\sin\left(3\theta+\dfrac{\pi}{2}\right)$?', '["$\\dfrac{2\\pi}{3}$", "$\\dfrac{\\pi}{2}$", "$2\\pi$", "$\\dfrac{4\\pi}{3}$"]'::jsonb, 0, 'A phase shift added inside the sine does not change the period. Since the coefficient of $\theta$ is $3$, the period is still $\dfrac{2\pi}{3}$.', 'Circular Measure', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A signal is given by $\sin(100\pi t)+\sin(300\pi t)$, with $t$ measured in seconds. What is the period of this signal?', '["$\\dfrac{1}{50}$ s", "$\\dfrac{1}{100}$ s", "$\\dfrac{1}{150}$ s", "$\\dfrac{1}{300}$ s"]'::jsonb, 0, 'The first term has period $\dfrac{2\pi}{100\pi}=\dfrac{1}{50}$ s and the second has period $\dfrac{2\pi}{300\pi}=\dfrac{1}{150}$ s. The period of the sum is the lowest common multiple of the two periods. Since $3\times\dfrac{1}{150}=\dfrac{1}{50}$, the combined period is $\dfrac{1}{50}$ s.', 'Circular Measure', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the period of $\sin\left(\dfrac{\theta}{2}\right)-\sin\left(\dfrac{\theta}{3}\right)$?', '["$12\\pi$", "$6\\pi$", "$4\\pi$", "$24\\pi$"]'::jsonb, 0, 'The first term has period $4\pi$ and the second has period $6\pi$. The period of the combined wave is the lowest common multiple of $4\pi$ and $6\pi$, which is $12\pi$.', 'Circular Measure', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the period of $\sin(4\theta)+\sin(2\theta)$?', '["$\\pi$", "$\\dfrac{\\pi}{2}$", "$2\\pi$", "$4\\pi$"]'::jsonb, 0, 'The first term has period $\dfrac{2\pi}{4}=\dfrac{\pi}{2}$ and the second has period $\dfrac{2\pi}{2}=\pi$. The lowest common multiple of $\dfrac{\pi}{2}$ and $\pi$ is $\pi$, so the sum has period $\pi$.', 'Circular Measure', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is $(2+3i)(3+2i)$?', '["$13i$", "$6+13i$", "$0+6i$", "$13+0i$"]'::jsonb, 0, 'Expanding: $(2+3i)(3+2i)=6+4i+9i+6i^2=6+13i-6=13i$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is $\dfrac{3+2i}{4-i}$ expressed in the form $a+bi$?', '["$\\dfrac{10}{17}+\\dfrac{11}{17}i$", "$\\dfrac{10}{17}-\\dfrac{11}{17}i$", "$\\dfrac{11}{17}+\\dfrac{10}{17}i$", "$\\dfrac{14}{17}+\\dfrac{5}{17}i$"]'::jsonb, 0, 'Multiplying numerator and denominator by the conjugate $4+i$: $\dfrac{(3+2i)(4+i)}{(4-i)(4+i)}=\dfrac{10+11i}{17}=\dfrac{10}{17}+\dfrac{11}{17}i$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the modulus of $(2+3i)(3-2i)$?', '["$13$", "$5$", "$\\sqrt{13}$", "$169$"]'::jsonb, 0, '$(2+3i)(3-2i)=12+5i$, so the modulus is $\sqrt{12^2+5^2}=\sqrt{169}=13$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the principal argument of $(2+3i)(3-2i)$?', '["$\\text{Arctan}\\dfrac{5}{12}$", "$\\text{Arctan}\\dfrac{12}{5}$", "$\\pi-\\text{Arctan}\\dfrac{5}{12}$", "$-\\text{Arctan}\\dfrac{5}{12}$"]'::jsonb, 0, '$(2+3i)(3-2i)=12+5i$, which lies in the first quadrant, so its principal argument is $\text{Arctan}\dfrac{5}{12}$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is $\dfrac{1}{(2+i)^2}-\dfrac{1}{(2-i)^2}$?', '["$-\\dfrac{8}{25}i$", "$\\dfrac{8}{25}i$", "$-\\dfrac{6}{25}i$", "$\\dfrac{3}{25}+\\dfrac{4}{25}i$"]'::jsonb, 0, '$(2+i)^2=3+4i$ and $(2-i)^2=3-4i$. Then $\dfrac{1}{3+4i}-\dfrac{1}{3-4i}=\dfrac{(3-4i)-(3+4i)}{(3+4i)(3-4i)}=\dfrac{-8i}{25}$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the modulus of $z=\dfrac{1+\sqrt2+i}{1-i}$?', '["$\\sqrt{2+\\sqrt2}$", "$\\sqrt{2-\\sqrt2}$", "$1+\\sqrt2$", "$\\sqrt{3+\\sqrt2}$"]'::jsonb, 0, 'Multiplying numerator and denominator by $1+i$ gives $z=\dfrac{\sqrt2}{2}+\left(1+\dfrac{\sqrt2}{2}\right)i$. Its modulus is $\sqrt{\left(\frac{\sqrt2}{2}\right)^2+\left(1+\frac{\sqrt2}{2}\right)^2}=\sqrt{2+\sqrt2}$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the principal argument of $z=\dfrac{1+\sqrt2+i}{1-i}$?', '["$\\dfrac{3\\pi}{8}$", "$\\dfrac{\\pi}{4}$", "$\\dfrac{\\pi}{8}$", "$\\dfrac{5\\pi}{8}$"]'::jsonb, 0, 'Writing $z=\dfrac{\sqrt2}{2}+\left(1+\dfrac{\sqrt2}{2}\right)i$, its argument is $\text{Arctan}\!\left(1+\sqrt2\right)$, which equals $\dfrac{3\pi}{8}$ (that is, $67.5^\circ$).', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is $(4+3i)+(6+4i)$?', '["$10+7i$", "$10+i$", "$2+i$", "$24+12i$"]'::jsonb, 0, 'Adding real and imaginary parts separately: $(4+6)+(3+4)i=10+7i$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is $(2-3i)-\overline{(4-5i)}$, where the overline denotes the complex conjugate?', '["$-2-8i$", "$-2+8i$", "$-2-2i$", "$6-8i$"]'::jsonb, 0, '$\overline{4-5i}=4+5i$, so $(2-3i)-(4+5i)=-2-8i$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is $\dfrac{3+4i}{6+3i}$ expressed in the form $a+bi$?', '["$\\dfrac23+\\dfrac13 i$", "$\\dfrac13+\\dfrac23 i$", "$\\dfrac25+\\dfrac13 i$", "$\\dfrac12+\\dfrac13 i$"]'::jsonb, 0, 'Multiplying numerator and denominator by the conjugate $6-3i$: $\dfrac{(3+4i)(6-3i)}{(6+3i)(6-3i)}=\dfrac{30+15i}{45}=\dfrac23+\dfrac13i$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is $\dfrac{1}{(2-i)^2}$ expressed in the form $a+bi$?', '["$\\dfrac{3}{25}+\\dfrac{4}{25}i$", "$\\dfrac{3}{25}-\\dfrac{4}{25}i$", "$\\dfrac{4}{25}+\\dfrac{3}{25}i$", "$\\dfrac{1}{25}+\\dfrac{4}{25}i$"]'::jsonb, 0, '$(2-i)^2=3-4i$, so $\dfrac{1}{3-4i}=\dfrac{3+4i}{(3-4i)(3+4i)}=\dfrac{3+4i}{25}=\dfrac{3}{25}+\dfrac{4}{25}i$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the principal argument of the complex number $i$?', '["$\\dfrac{\\pi}{2}$", "$\\pi$", "$-\\dfrac{\\pi}{2}$", "$0$"]'::jsonb, 0, '$i=0+1i$ lies on the positive imaginary axis, so its principal argument is $\dfrac{\pi}{2}$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the principal argument of the complex number $-1-i$?', '["$-\\dfrac{3\\pi}{4}$", "$\\dfrac{3\\pi}{4}$", "$\\dfrac{5\\pi}{4}$", "$-\\dfrac{\\pi}{4}$"]'::jsonb, 0, '$-1-i$ lies in the third quadrant, and its reference angle is $\dfrac{\pi}{4}$. The principal argument, restricted to $(-\pi,\pi]$, is therefore $-\pi+\dfrac{\pi}{4}=-\dfrac{3\pi}{4}$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the principal argument of the complex number $-\sqrt5$?', '["$\\pi$", "$0$", "$-\\pi$", "$\\dfrac{\\pi}{2}$"]'::jsonb, 0, '$-\sqrt5$ is a negative real number, lying on the negative real axis, whose principal argument is $\pi$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the modulus of $-1-i$?', '["$\\sqrt2$", "$2$", "$1$", "$\\sqrt3$"]'::jsonb, 0, 'The modulus is $\sqrt{(-1)^2+(-1)^2}=\sqrt2$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is $\dfrac{5+i}{2+3i}$ expressed in standard form?', '["$1-i$", "$1+i$", "$-1+i$", "$2-i$"]'::jsonb, 0, 'Multiplying numerator and denominator by the conjugate $2-3i$: $\dfrac{(5+i)(2-3i)}{(2+3i)(2-3i)}=\dfrac{13-13i}{13}=1-i$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'In a parallelogram $OABC$, the side $OA$ represents the complex number $2+4i$ and the diagonal $OB$ represents $5+i$. What complex number does the side $OC$ represent?', '["$3-3i$", "$7+5i$", "$-3+3i$", "$3+3i$"]'::jsonb, 0, 'In parallelogram $OABC$, the diagonal from $O$ satisfies $OB=OA+OC$, so $OC=OB-OA=(5+i)-(2+4i)=3-3i$.', 'Complex Numbers', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Using the expansion of $(\cos\theta+i\sin\theta)^3$, how can $\cos3\theta$ be expressed in terms of $\cos\theta$ alone?', '["$4\\cos^3\\theta-3\\cos\\theta$", "$3\\cos\\theta-4\\cos^3\\theta$", "$4\\cos^3\\theta-3\\cos^2\\theta$", "$\\cos^3\\theta-3\\cos\\theta$"]'::jsonb, 0, 'By De Moivre''s theorem, $\cos3\theta+i\sin3\theta=(\cos\theta+i\sin\theta)^3$. Expanding and equating real parts, using $\sin^2\theta=1-\cos^2\theta$, gives $\cos3\theta=4\cos^3\theta-3\cos\theta$.', 'De Moivre''s Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Using the expansion of $(\cos\theta+i\sin\theta)^3$, how can $\sin3\theta$ be expressed in terms of $\sin\theta$ alone?', '["$3\\sin\\theta-4\\sin^3\\theta$", "$4\\sin^3\\theta-3\\sin\\theta$", "$3\\sin\\theta-\\sin^3\\theta$", "$4\\sin^3\\theta-3\\sin^2\\theta$"]'::jsonb, 0, 'By De Moivre''s theorem, $\cos3\theta+i\sin3\theta=(\cos\theta+i\sin\theta)^3$. Expanding and equating imaginary parts, using $\cos^2\theta=1-\sin^2\theta$, gives $\sin3\theta=3\sin\theta-4\sin^3\theta$.', 'De Moivre''s Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $z=\cos\theta+i\sin\theta$, what does $z^n+z^{-n}$ equal, for integer $n$?', '["$2\\cos(n\\theta)$", "$2\\sin(n\\theta)$", "$2i\\sin(n\\theta)$", "$\\cos(n\\theta)$"]'::jsonb, 0, 'By De Moivre''s theorem, $z^n=\cos n\theta+i\sin n\theta$ and $z^{-n}=\cos n\theta-i\sin n\theta$. Adding these gives $z^n+z^{-n}=2\cos(n\theta)$.', 'De Moivre''s Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'One value of $(-1+i\sqrt3)^{1/4}$ has modulus $2^{1/4}$. What is its argument, taking the smallest nonnegative value?', '["$\\dfrac{\\pi}{6}$", "$\\dfrac{2\\pi}{3}$", "$\\dfrac{\\pi}{3}$", "$\\dfrac{\\pi}{12}$"]'::jsonb, 0, '$-1+i\sqrt3$ has modulus $2$ and argument $\dfrac{2\pi}{3}$. Its fourth roots have argument $\dfrac{\frac{2\pi}{3}+2k\pi}{4}$ for $k=0,1,2,3$; taking $k=0$ gives $\dfrac{\pi}{6}$, the smallest nonnegative value.', 'De Moivre''s Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'A complex number has modulus twice that of $4+3i$. What is its modulus?', '["$10$", "$5$", "$7$", "$25$"]'::jsonb, 0, 'The modulus of $4+3i$ is $\sqrt{4^2+3^2}=5$, so twice this modulus is $10$.', 'De Moivre''s Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the modulus of a cube root of $1-i$?', '["$2^{1/6}$", "$2^{1/3}$", "$2^{1/2}$", "$\\sqrt[3]{2}$"]'::jsonb, 0, '$1-i$ has modulus $\sqrt2$, so each of its cube roots has modulus $(\sqrt2)^{1/3}=2^{1/6}$.', 'De Moivre''s Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'One cube root of $1-i$, obtained by taking the smallest possible magnitude of argument, has what argument?', '["$-\\dfrac{\\pi}{12}$", "$-\\dfrac{\\pi}{4}$", "$\\dfrac{\\pi}{12}$", "$\\dfrac{7\\pi}{12}$"]'::jsonb, 0, '$1-i$ has principal argument $-\dfrac{\pi}{4}$. Dividing by $3$ (the case $k=0$ in De Moivre''s theorem for roots) gives an argument of $-\dfrac{\pi}{12}$ for one cube root.', 'De Moivre''s Theorem', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\omega=\dfrac{-1+i\sqrt3}{2}$, what is $\omega^3$?', '["$1$", "$-1$", "$\\omega$", "$0$"]'::jsonb, 0, '$\omega$ is a primitive cube root of unity, meaning $\omega^3=1$ by construction, since $\omega=\cos120^\circ+i\sin120^\circ$ and $(\cos120^\circ+i\sin120^\circ)^3=\cos360^\circ+i\sin360^\circ=1$.', 'Roots of Unity', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\omega=\dfrac{-1+i\sqrt3}{2}$, what is $1+\omega+\omega^2$?', '["$0$", "$1$", "$3$", "$-1$"]'::jsonb, 0, 'The three cube roots of unity, $1,\omega,\omega^2$, always sum to zero, since they are the roots of $z^3-1=(z-1)(z^2+z+1)=0$ and $z^2+z+1=0$ has roots $\omega,\omega^2$ summing to $-1$; adding the root $z=1$ gives a total of $0$.', 'Roots of Unity', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Let $\alpha=\cos\dfrac{2\pi}{3}+i\sin\dfrac{2\pi}{3}$. If $n$ is a multiple of $3$, what is $1+\alpha^n+\alpha^{2n}$?', '["$3$", "$0$", "$1$", "$-1$"]'::jsonb, 0, 'If $n=3k$, then $\alpha^n=(\alpha^3)^k=1^k=1$ since $\alpha^3=1$, and likewise $\alpha^{2n}=1$. So $1+\alpha^n+\alpha^{2n}=1+1+1=3$.', 'Roots of Unity', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'Let $\alpha=\cos\dfrac{2\pi}{3}+i\sin\dfrac{2\pi}{3}$. If $n$ is not a multiple of $3$, what is $1+\alpha^n+\alpha^{2n}$?', '["$0$", "$3$", "$1$", "$-1$"]'::jsonb, 0, 'When $n$ is not a multiple of $3$, $\alpha^n$ is one of the two nontrivial cube roots of unity, and $1+\alpha^n+(\alpha^n)^2=0$ since $1,\alpha^n,\alpha^{2n}$ are then precisely the three cube roots of unity, which sum to zero.', 'Roots of Unity', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'The equation $z^5+1=0$ has one root with the smallest positive argument. What is that argument?', '["$36^\\circ$", "$72^\\circ$", "$180^\\circ$", "$60^\\circ$"]'::jsonb, 0, 'Writing $-1=\cos180^\circ+i\sin180^\circ$, the fifth roots have arguments $\dfrac{180^\circ+360^\circ k}{5}$ for $k=0,1,2,3,4$, i.e. $36^\circ,108^\circ,180^\circ,252^\circ,324^\circ$. The smallest positive one is $36^\circ$.', 'Roots of Unity', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'How many distinct solutions does the equation $z^5+1=0$ have in the complex numbers?', '["5", "1", "10", "4"]'::jsonb, 0, 'A nonzero complex number always has exactly $n$ distinct $n$th roots. Since $z^5=-1$ asks for the fifth roots of the nonzero number $-1$, there are exactly $5$ distinct solutions.', 'Roots of Unity', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'The four fourth roots of $i$ are equally spaced around a circle of radius $1$. What is the argument of the root with the smallest nonnegative argument?', '["$22.5^\\circ$", "$45^\\circ$", "$90^\\circ$", "$67.5^\\circ$"]'::jsonb, 0, 'Since $i=\cos90^\circ+i\sin90^\circ$, its fourth roots have arguments $\dfrac{90^\circ+360^\circ k}{4}$ for $k=0,1,2,3$. Taking $k=0$ gives $22.5^\circ$, the smallest nonnegative value.', 'Roots of Unity', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'The four fourth roots of $i$ are equally spaced around a circle centred at the origin. What is the radius of that circle?', '["$1$", "$4$", "$\\dfrac14$", "$2$"]'::jsonb, 0, 'Since $|i|=1$, every fourth root of $i$ also has modulus $1^{1/4}=1$, so the roots lie on the unit circle.', 'Roots of Unity', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the sum of all three cube roots of unity?', '["$0$", "$1$", "$3$", "$-1$"]'::jsonb, 0, 'The cube roots of unity are $1,\omega,\omega^2$ where $\omega=\cos120^\circ+i\sin120^\circ$. They are the roots of $z^3-1=0$, whose coefficient of $z^2$ is $0$, so by Vieta''s formula their sum is $0$.', 'Roots of Unity', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the product of all five fifth roots of unity?', '["$1$", "$0$", "$-1$", "$5$"]'::jsonb, 0, 'The fifth roots of unity are the roots of $z^5-1=0$. By Vieta''s formula, the product of the roots of $z^5-1=0$ is $(-1)^5\times(-1)=1$.', 'Roots of Unity', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\sec(\text{Arctan}\,2)$?', '["$\\sqrt{5}$", "$\\sqrt{3}$", "$2$", "$\\dfrac{1}{\\sqrt5}$"]'::jsonb, 0, 'If $\theta=\text{Arctan}\,2$ then $\tan\theta=2$ with $\theta$ in the first quadrant, so a right triangle gives opposite $2$, adjacent $1$, hypotenuse $\sqrt5$. Thus $\sec\theta=\sqrt5$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\cos(\text{Arctan}\,1)$?', '["$\\dfrac{\\sqrt2}{2}$", "$1$", "$\\dfrac{1}{2}$", "$\\dfrac{\\sqrt3}{2}$"]'::jsonb, 0, '$\text{Arctan}\,1=\dfrac{\pi}{4}$, and $\cos\dfrac{\pi}{4}=\dfrac{\sqrt2}{2}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\cot(\text{Arccos}\,0)$?', '["$0$", "$1$", "undefined", "$-1$"]'::jsonb, 0, '$\text{Arccos}\,0=\dfrac{\pi}{2}$, and $\cot\dfrac{\pi}{2}=0$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\tan(\text{Arccos}\,1)$?', '["$0$", "undefined", "$1$", "$-1$"]'::jsonb, 0, '$\text{Arccos}\,1=0$, and $\tan 0 = 0$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\text{Arcsin}(-0.5)$?', '["$-30^\\circ$", "$30^\\circ$", "$-60^\\circ$", "$210^\\circ$"]'::jsonb, 0, 'The principal range of Arcsin is $[-90^\circ,90^\circ]$, and $\sin(-30^\circ)=-0.5$, so $\text{Arcsin}(-0.5)=-30^\circ$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\text{cosec}(\text{Arcsec}\,2)$?', '["$\\dfrac{2\\sqrt3}{3}$", "$\\dfrac{\\sqrt3}{2}$", "$2$", "$\\dfrac{1}{2}$"]'::jsonb, 0, 'If $\theta=\text{Arcsec}\,2$ then $\sec\theta=2$, i.e. $\cos\theta=\dfrac12$, so $\theta=60^\circ$ (the principal range of Arcsec places this angle in the first quadrant). Then $\sin\theta=\dfrac{\sqrt3}{2}$, so $\text{cosec}\,\theta=\dfrac{2}{\sqrt3}=\dfrac{2\sqrt3}{3}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\sin(\text{Arccos}\,0.5)$?', '["$\\dfrac{\\sqrt3}{2}$", "$\\dfrac12$", "$\\dfrac{\\sqrt2}{2}$", "$1$"]'::jsonb, 0, '$\text{Arccos}\,0.5=60^\circ$, and $\sin60^\circ=\dfrac{\sqrt3}{2}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the value of $\sin(\text{Arctan}(-1))$?', '["$-\\dfrac{\\sqrt2}{2}$", "$\\dfrac{\\sqrt2}{2}$", "$-1$", "$-\\dfrac12$"]'::jsonb, 0, '$\text{Arctan}(-1)=-45^\circ$, and $\sin(-45^\circ)=-\dfrac{\sqrt2}{2}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is the exact value of $\tan\!\left(4\,\text{Arctan}\dfrac15-\text{Arctan}\,1\right)$?', '["$\\dfrac{1}{239}$", "$\\dfrac{1}{5}$", "$1$", "$\\dfrac{4}{5}$"]'::jsonb, 0, 'Using the tangent addition formula repeatedly on $4\,\text{Arctan}\frac15$ gives $\tan\!\left(4\,\text{Arctan}\frac15\right)=\frac{120}{119}$. Subtracting $\text{Arctan}\,1$ (whose tangent is $1$) with the subtraction formula gives $\dfrac{\frac{120}{119}-1}{1+\frac{120}{119}}=\dfrac{1}{239}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\theta=\text{Arctan}(-1.1106)$, what is $\theta$ (to the nearest degree)?', '["$-48^\\circ$", "$48^\\circ$", "$132^\\circ$", "$-42^\\circ$"]'::jsonb, 0, 'The tangent is negative, so with the principal range of Arctan being $(-90^\circ,90^\circ)$, $\theta$ must be a negative angle in the fourth quadrant. Since the acute angle with tangent $1.1106$ is $48^\circ$, $\theta=-48^\circ$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\theta=\text{Arcsec}\dfrac{29}{21}$, what is $\sin\theta$?', '["$\\dfrac{20}{29}$", "$\\dfrac{21}{29}$", "$\\dfrac{20}{21}$", "$\\dfrac{29}{20}$"]'::jsonb, 0, '$\sec\theta=\dfrac{29}{21}$ gives $\cos\theta=\dfrac{21}{29}$. Since Arcsec has a nonnegative principal range, $\sin\theta\ge0$, and by the 20-21-29 right triangle, $\sin\theta=\sqrt{1-\left(\frac{21}{29}\right)^2}=\dfrac{20}{29}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What is $\text{Arcsin}(0.6382)$, to the nearest tenth of a degree?', '["$39.7^\\circ$", "$36.4^\\circ$", "$50.3^\\circ$", "$63.8^\\circ$"]'::jsonb, 0, 'Taking the inverse sine of $0.6382$ directly gives approximately $39.66^\circ$, which rounds to $39.7^\circ$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are the solutions of $2\cos^2\theta+\cos\theta-1=0$ for $\theta$ in $[0^\circ,360^\circ)$?', '["$60^\\circ,\\ 180^\\circ,\\ 300^\\circ$", "$60^\\circ,\\ 300^\\circ$", "$120^\\circ,\\ 180^\\circ,\\ 240^\\circ$", "$60^\\circ,\\ 180^\\circ$"]'::jsonb, 0, 'Treating this as a quadratic in $\cos\theta$ gives $\cos\theta=\tfrac12$ or $\cos\theta=-1$. The first yields $\theta=60^\circ$ or $300^\circ$, and the second yields $\theta=180^\circ$. All three lie in $[0^\circ,360^\circ)$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are the solutions of $\cot\theta=2$ for $\theta$ in $[0^\circ,360^\circ)$, to the nearest hundredth of a degree?', '["$26.57^\\circ,\\ 206.57^\\circ$", "$63.43^\\circ,\\ 243.43^\\circ$", "$26.57^\\circ,\\ 153.43^\\circ$", "$26.57^\\circ$ only"]'::jsonb, 0, '$\cot\theta=2$ means $\tan\theta=0.5$, so $\theta=\text{Arctan}(0.5)\approx26.57^\circ$, together with the second solution obtained by adding $180^\circ$ (tangent''s period), giving $206.57^\circ$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are the solutions of $\cot\theta=1$ for $\theta$ in $[0^\circ,360^\circ)$?', '["$45^\\circ,\\ 225^\\circ$", "$45^\\circ,\\ 315^\\circ$", "$45^\\circ$ only", "$135^\\circ,\\ 315^\\circ$"]'::jsonb, 0, '$\cot\theta=1$ means $\tan\theta=1$, giving $\theta=45^\circ$ and, using the $180^\circ$ period of tangent, $\theta=225^\circ$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'If $\sin\theta=0.8090$ and $\cos\theta=-0.5878$ simultaneously, what is the primary value of $\theta$?', '["$126^\\circ$", "$54^\\circ$", "$234^\\circ$", "$-54^\\circ$"]'::jsonb, 0, 'Sine positive and cosine negative places $\theta$ in the second quadrant. Since the reference angle with sine $0.8090$ is $54^\circ$, the second-quadrant angle is $180^\circ-54^\circ=126^\circ$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are the primary solutions of $\cos^2\theta-\tan^2\theta=\sec^2\theta$ in $[0,2\pi)$?', '["$0$ and $\\pi$", "$\\dfrac{\\pi}{2}$ and $\\dfrac{3\\pi}{2}$", "$0$ only", "$\\dfrac{\\pi}{4}$ and $\\dfrac{5\\pi}{4}$"]'::jsonb, 0, 'Multiplying through by $\cos^2\theta$ and using $\sin^2\theta=1-\cos^2\theta$ reduces the equation to $\cos^4\theta+\cos^2\theta-2=0$, i.e. $(\cos^2\theta-1)(\cos^2\theta+2)=0$. Only $\cos^2\theta=1$ is possible, giving $\cos\theta=\pm1$, i.e. $\theta=0$ or $\pi$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'How many solutions does $\sin\theta\cos\theta=2\sin^2\theta\cos^2\theta$ have in $[0,2\pi)$?', '["6", "4", "2", "8"]'::jsonb, 0, 'Factoring gives $\sin\theta\cos\theta(2\sin\theta\cos\theta-1)=0$, i.e. $\tfrac12\sin2\theta(\sin2\theta-1)=0$. This requires $\sin2\theta=0$ (giving $\theta=0,\frac{\pi}{2},\pi,\frac{3\pi}{2}$) or $\sin2\theta=1$ (giving $\theta=\frac{\pi}{4},\frac{5\pi}{4}$), a total of 6 solutions in $[0,2\pi)$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are the primary solutions of $\sqrt3\cos\theta-\sin\theta=1$ in $[0^\circ,360^\circ)$?', '["$30^\\circ,\\ 270^\\circ$", "$30^\\circ,\\ 150^\\circ$", "$60^\\circ,\\ 300^\\circ$", "$90^\\circ,\\ 210^\\circ$"]'::jsonb, 0, 'Writing the left side as $2\cos(\theta+30^\circ)$, the equation becomes $\cos(\theta+30^\circ)=\tfrac12$, so $\theta+30^\circ=\pm60^\circ+360^\circ k$. This gives $\theta=30^\circ$ or $\theta=-90^\circ\equiv270^\circ$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are the solutions of $4\sin^2 t=3$ for $t$ in $[0,2\pi)$?', '["$\\dfrac{\\pi}{3},\\dfrac{2\\pi}{3},\\dfrac{4\\pi}{3},\\dfrac{5\\pi}{3}$", "$\\dfrac{\\pi}{3},\\dfrac{2\\pi}{3}$", "$\\dfrac{\\pi}{6},\\dfrac{5\\pi}{6},\\dfrac{7\\pi}{6},\\dfrac{11\\pi}{6}$", "$\\dfrac{\\pi}{3},\\dfrac{5\\pi}{3}$"]'::jsonb, 0, '$\sin^2 t=\tfrac34$ gives $\sin t=\pm\dfrac{\sqrt3}{2}$, whose solutions in $[0,2\pi)$ are $t=\dfrac{\pi}{3},\dfrac{2\pi}{3},\dfrac{4\pi}{3},\dfrac{5\pi}{3}$.', 'Trigonometric Functions', false, 'first', 3),
  ('mth-101-elementary-mathematics-1', 'MTH 101: Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Agriculture, Faculty of Biological Sciences, Faculty of Education, Faculty of Engineering, Faculty of Environmental Studies, Faculty of Physical Sciences, Faculty of Social Sciences, Faculty of Veterinary Medicine', 'Mathematics', '100 Level', 'What are the solutions of $2\sin^2\theta+3\cos\theta=0$ for $\theta$ in $[0^\circ,360^\circ)$?', '["$120^\\circ,\\ 240^\\circ$", "$60^\\circ,\\ 300^\\circ$", "$120^\\circ$ only", "$150^\\circ,\\ 210^\\circ$"]'::jsonb, 0, 'Using $\sin^2\theta=1-\cos^2\theta$ gives $-2\cos^2\theta+3\cos\theta+2=0$, i.e. $2\cos^2\theta-3\cos\theta-2=0$, which factors so that $\cos\theta=2$ (rejected) or $\cos\theta=-\tfrac12$. The latter gives $\theta=120^\circ$ or $240^\circ$.', 'Trigonometric Functions', false, 'first', 3);
